-- =====================================================================
-- Locale_401.lua — v4.0.1 Chat, Layout & Aura Quality of Life
-- =====================================================================

TomoMod_RegisterLocale("enUS", {
    ["section_blizzard_auras"]   = "Blizzard Aura Frames",
    ["info_blizzard_auras"]      = "Control Blizzard's default buff and debuff frames without affecting TomoMod unit-frame auras. Changes apply immediately and do not require a reload.",
    ["opt_blizzard_auras_manage"] = "Let TomoMod manage Blizzard aura frames",
    ["opt_blizzard_buffs"]       = "Show Blizzard buffs",
    ["opt_blizzard_debuffs"]     = "Show Blizzard debuffs",
    ["layout_configure"]         = "Configure this element",
    ["wn_401_layout_cogs"]       = "New — Layout Mode now shows a cog button when you hover a movable element. Click it to jump straight to the relevant TomoMod options page.",
    ["wn_401_blizzard_auras"]    = "New — Interface > General can now hide Blizzard's default buff and debuff frames independently, live and without a reload.",
    ["wn_401_chat_v4"]           = "New — Chat V4 rebuilds the chat presentation with a dark TomoMod shell for messages, docked tabs, the native input box and a new sidebar, while Blizzard remains responsible for chat delivery, formatting and secure interactions.",
    ["wn_401_chat_options"]      = "New — Skins > Chat Frame is now the live control centre for Chat V4. Enable it, tune background opacity and font size, choose message behaviour, customize the sidebar and set Copy Chat's line limit; every change applies immediately without a reload.",
    ["wn_401_chat_message_opacity"] = "New — Frame opacity and message-area opacity are now separate. The second slider changes only the background behind chat text, down to fully transparent, without fading tabs, sidebar or input; existing profiles keep their previous appearance.",
    ["wn_401_chat_messages"]     = "New — Message presentation can add or preserve timestamps, abbreviate localized channel names, fade after two minutes, turn familiar smileys into symbols and colour known player mentions by class. Changing an option rebuilds existing lines so the whole visible history stays consistent.",
    ["wn_401_chat_urls"]         = "New — Plain HTTP(S) and www addresses become teal clickable links without disturbing Blizzard's existing hyperlinks. Clicking one opens a focused Ctrl+C popup, and sentence-ending punctuation stays outside the link.",
    ["wn_401_chat_sidebar_options"] = "New — Move the sidebar left or right, adjust its width, button size and spacing, show or hide every shortcut, and choose between 50 and 1,000 Copy Chat lines. Existing Chat Skin message settings migrate once into Chat V4.",
    ["wn_401_chat_wiring"]       = "Changed — Chat V4 is now the single public chat module across defaults, the module registry, dashboard, installer, presets, profile imports and resolution scaling. Legacy chat databases remain internal migration sources only.",
    ["wn_401_chat_combatlog"]    = "Changed — The Combat Log now uses the Chat V4 surface when selected, while Blizzard still filters and formats every line first. TomoMod mirrors only the final output and never replaces the combat-log APIs.",
    ["wn_401_chat_journal_controls"] = "New — Blizzard's Combat Log quick-filter bar now docks at the top of the Chat V4 message area, which reserves space for it. It hides on other tabs and returns to its exact original position and visibility when Chat V4 is disabled, without reparenting or replacing the filters.",
    ["wn_401_chat_phase21_polish"] = "Changed — Mirrored tabs now stay inside the panel's top border. The Emotes shortcut has been removed from the sidebar and options, including old saved layouts, while Copy Chat, Loot, Settings and Scroll to Bottom are arranged cleanly in pairs.",
    ["wn_401_chat_tabs"]         = "New — Chat V4 tabs are now interactive controls arranged left-to-right inside their own strip, including an undocked Combat Log. Left and right clicks are forwarded to the invisible Blizzard tab, preserving native selection and context menus while keeping the active underline and unread indicator in sync.",
    ["wn_401_chat_native_chrome"] = "Fixed — Native chat backgrounds, NineSlice borders and resize handles stay hidden even after selecting General or Combat Log. Chat V4 captures each original alpha before hiding the artwork and restores it exactly when disabled.",
    ["wn_401_chat_sidebar"]      = "New — The redesigned sidebar adds custom icons and live state colours for Friends, Guild, Online/AFK/DND, voice, mute and deafen, plus online counts and shortcuts for Chat Copy, Loot Browser, TomoMod settings and scroll-to-bottom.",
    ["wn_401_chat_sidebar_assets"] = "Changed — Sidebar icons now use dedicated replaceable 64×64 transparent textures, including status, mute and deafen variants. All ten hover titles and descriptions, plus the Online/Away/Do Not Disturb menu, are localized in all six supported languages.",
    ["wn_401_chat_copy"]         = "New — Copy Chat is restored as a full TomoMod window: it reads the active Blizzard tab live when opened, is movable and resizable, follows the chat font size, and provides localized Select All and Close controls with a modern scrollbar and a compatible fallback.",
    ["wn_401_chat_copy_clean"]   = "Changed — Copied chat becomes readable text while preserving message colours, raid markers, link labels and resolvable Battle.net names. UI artwork and control codes are removed, protected values are skipped, shorter transcripts are selected automatically, and the view opens at the newest line.",
    ["wn_401_chat_safe"]         = "Changed — Chat V4 mirrors Blizzard's chat instead of replacing its secure path. Blizzard remains the Combat Log filtering authority, no FCF function is hooked, and disabling Chat V4 restores the native chat presentation.",
    ["wn_401_chat_links"]        = "Fixed — Player names, channel labels, item links and other Blizzard hyperlinks are clickable again in Chat V4. The message surface forwards them to Blizzard's native link handler, while TomoMod web links still open the copy popup.",
    ["wn_401_chat_mover"]        = "Fixed — Chat V4 now has a real mover in TomoMod Layout Mode. Dragging its full-panel overlay moves the underlying Blizzard chat and input box live, saves the new position, and temporarily releases mouse capture in both TomoMod Layout Mode and Blizzard Edit Mode before restoring links and scrolling.",
    ["wn_401_chat_community"]    = "New — A localized Community tab combines incoming and outgoing character whispers, Battle.net private messages, Guild chat and Officer chat from every Blizzard chat window. Duplicate deliveries are removed by line ID, while clickable links, unread state, native text entry and Copy Chat remain available.",
    ["wn_401_objective_chrome"]  = "Fixed — Blizzard's full Objective Tracker backdrop and animated header backgrounds can no longer reappear behind TomoMod after a tracker refresh. Their original alpha values are restored when the TomoMod tracker is disabled.",
    ["wn_401_castbar_lifecycle"]  = "Fixed — Your cast bar no longer disappears halfway through a long cast. An instant spell or a proc going off while you were still casting was closing the bar of the spell you were actually casting; only the real end of that cast closes it now.",
    ["wn_401_castbar_identity"]   = "Fixed — A cast bar now only reacts to its own cast. The stop, failure or interrupt of another spell can no longer close it or flash it red, because each bar remembers which cast opened it and checks every ending event against that.",
    ["wn_401_castbar_stale"]      = "New — A cast bar that stops hearing from the server closes itself a second after the cast should have ended. A lost message during a latency spike or a reconnection mid-cast used to be able to leave a bar frozen on screen; empowered spells are left alone, since they are meant to hold past their announced end until you release them.",
    ["wn_401_castbar_preview"]    = "Fixed — Layout Mode and the options preview no longer fight over the player cast bar. You can move it from Layout Mode without opening the options window, closing one no longer cancels the other, and entering combat closes any preview at once so it can never sit on top of a real cast.",
    ["wn_401_layout_chat_route"]  = "Fixed — The Layout Mode cog is back on the chat window. It was still pointing at the frames of the old chat skin, which Chat V4 replaced, so hovering the chat panel offered no shortcut to its settings.",
    ["wn_401_bags_v4"]            = "New — Bags V4 replaces the old bag skin with a window TomoMod owns from end to end: every bag in one grid, the number of used and total slots in the header, your money in the footer, and a frame you can drag wherever you like. Blizzard still owns every item action, so clicking, dragging, selling and tooltips work exactly as they always have.",
    ["wn_401_bags_search_sort"]   = "New — Search your bags as you type, by item name or item ID, and cycle the display between bag order, quality, name and item level from the header button. The sort is purely visual: nothing is ever moved inside your real bags, so it cannot be interrupted halfway or argue with the server.",
    ["wn_401_bags_sidebar"]       = "New — A sidebar keeps your pinned and recent items in view. Middle-click any item to pin it and the pin stays with your profile; anything new that arrives in your bags shows up under Recent. Left-click a sidebar tile to find that item in the grid.",
    ["wn_401_bags_slots"]         = "New — Slots are drawn with quality-coloured borders, the item level on weapons and armour, a mark on pinned items and a dimmed icon on locked ones. Stack counts and cooldown swipes still come from the game itself, and reagent bags are included wherever the client has them. Borders, item level and empty slots can each be switched off.",
    ["wn_401_bags_native"]        = "Changed — Opening and closing follows the game. Your bag keybinds, the micro menu, vendors, the mailbox and the bank all still open the window, and Blizzard's own bag frames are parked out of sight while Bags V4 is on and handed straight back the moment you turn it off.",
    ["wn_401_bags_combat"]        = "New — Bags V4 never builds or moves a slot while you are in combat. Anything it cannot do safely is queued and applied the moment the fight ends, while icons, stack counts, locks and cooldowns keep updating throughout.",
    ["wn_401_bags_migration"]     = "Changed — Your existing bag settings move across once: opacity, scale, slot size, spacing, column count, sorting, quality borders, item level, empty slots, the search bar and the window position. The Home dashboard now initializes and controls Bags V4 directly: turning it off closes the custom window and restores Blizzard's bags, while the installer and presets remain synchronized through the legacy flag.",
    ["wn_401_bags_display_mode"]  = "New — Choose how your bags open. Combined keeps everything in the single TomoMod window; Separate hands them back to Blizzard's individual bag windows and steps out of the way entirely, putting the game's own combined-bags setting back where it belongs.",
    ["wn_401_bags_options"]       = "New — Skins > Bags is now a live settings page. Display mode, columns, slot size and spacing, scale, opacity, visual sorting, the search bar, quality borders, item level, empty slots and how many pinned and recent tiles the sidebar keeps — every one of them applies immediately, with no reload.",
    ["wn_401_bags_render"]        = "Fixed — Bag slots now use a minimal renderer independent of Blizzard's private icon and count regions: the visible icon, stack count and cooldown are TomoMod layers, while the native item button retains every secure action. Valid Midnight slots can no longer appear empty.",
    ["wn_401_bags_native_restore"] = "Changed — Blizzard's private icon and count regions stay transparent; TomoMod draws the visible icon, quantity and cooldown on simple independent layers. Fixed bag/slot contents still refresh in combat, while only layout changes wait until combat ends.",
    ["wn_401_bags_interactions"]  = "Fixed — Slots keep Blizzard's native secure left/right click and drag paths untouched. Tooltips are added with hooks rather than replacing the template scripts, while middle mouse is observed separately for pinning and TomoMod's visual overlays remain non-interactive.",
    ["wn_401_bags_button_visibility"] = "Fixed — Every secure item button is explicitly shown when created, rendered and placed in the grid, preventing a hidden pooled state from leaving a visible slot empty or unable to receive clicks.",
    ["wn_401_bags_empty_quality"] = "Changed — Empty slots use a minimal dark fill and soft border, while quality borders remain strong above common and subdued below. Item level sits top-left on its own contrast plate, away from the bottom-right stack count.",
    ["wn_401_bags_text_polish"]   = "Changed — Stack quantities and item levels scale with the selected slot size and sit on subtle dark plates for contrast. Quantities stay bottom-right and item levels top-left so the two labels no longer overlap.",
    ["wn_401_bags_surface_polish"] = "Changed — Bags V4 surfaces, header, search area, sidebar and footer are slightly brighter. Empty Pinned and Recent messages use clearer colour, dynamic width and up to two wrapped lines so every translation fits.",
    ["wn_401_bags_fit"]           = "New — The combined window now fits the actual displayed item count. It keeps the requested column count when possible, adds columns before introducing a scrollbar when height is tight, and shows scrolling only when no on-screen geometry can contain the complete grid; an unnecessary scrollbar stays hidden.",
    ["wn_401_bags_slot_identity"] = "Changed — Bag slots now identify their purpose at a glance: ordinary bag space uses a mint/teal outline, while reagent-bag space uses an azure-white outline. Occupied slots still use item-quality colours when quality borders are enabled; otherwise they retain their bag-type outline.",
    ["wn_401_mplus_score_columns"] = "Fixed — The Score Planner's Current Score, Target Score, Estimated Gain and Potential columns now share the available card width instead of using fixed positions. Potential no longer extends beyond the right edge at the default Studio size or when text scaling is increased.",
    ["wn_401_actionbar_negative_spacing"] = "Fixed — Action buttons with negative spacing no longer overlap their clickable areas. TomoMod splits shared pixels at the midpoint, so clicking or dragging a spell always targets the button under the pointer; zero and positive spacing keep their full hit boxes.",
    ["wn_401_raid_position"]      = "Fixed — Raid-frame positions now use the shared Layout Engine when saved and restored. Existing position formats remain compatible, and moved raid frames no longer jump after a reload or a resolution or UI-scale change.",
    ["wn_401_class_reminder_position"] = "Fixed — Class Reminder now migrates its saved anchor, rescales it for the current resolution and converts offsets through its own frame scale. It no longer drifts after a reload or display change.",
    ["wn_401_objective_position"] = "Fixed — Objective Tracker positions now understand both legacy and Layout V4 anchors, rescale from the saved resolution and account for the tracker's own scale. The tracker no longer changes anchor or creeps across the screen after a reload or display change.",
    ["wn_401_layout_scaled_positions"] = "Fixed — Layout V4 now saves offsets in UIParent units and converts them back through each frame's effective scale when restoring. Scaled frames no longer multiply their coordinates and drift after repeated reloads.",
    ["wn_401_layout_minimap"]     = "Fixed — The Minimap's exceptional legacy coordinates are normalized once into Layout V4 without moving it. Physical-position checks ignore harmless internal re-anchoring by Blizzard, preventing jumps and one-frame misalignment with the surrounding chrome.",
    ["wn_401_layout_secondary_frames"] = "Changed — The player cast bar, Resource Bars and Battle Resurrection counter now save and restore through the shared Layout Engine. Their positions remain stable across reloads and changes of UI scale or resolution, with compatibility fallbacks retained.",
    ["wn_401_layout_mythic_tracker"] = "Fixed — The Mythic+ Tracker now applies scale before its V4 position and uses the same engine for drags, resets and Layout Mode previews. Cancelling positioning in the Studio restores the complete saved position instead of downgrading it to the legacy format.",
    ["wn_401_layout_v4_anchors"]  = "New — Chat V4 and Bags V4 now declare their real movable anchors to Layout V4. Position migration, resolution presets, reference stamping and selective imports can include the current frames instead of obsolete legacy chat anchors.",
    ["wn_401_bags_position"]      = "Fixed — Bags V4 now saves the window's physical position after a drag and restores it through Layout V4. Moving or scaling the bags no longer reuses pre-drag offsets or makes the window drift after later reloads.",
    ["wn_401_layout_v4_routes"]   = "Fixed — Layout Mode cogs on TUI action bars and Bags V4 now open the correct Action Bars or Skins settings page. Automated coverage also checks that every declared movable anchor has a live options route.",
    ["wn_401_layout_pixel_perfect"] = "New — Layout V4.1 can align every position saved through the shared layout engine to the nearest physical display pixel. It derives the real pixel size from the physical resolution, remains optional and leaves existing V4 behaviour unchanged while disabled.",
    ["wn_401_layout_nudger"]      = "New — Layout Mode gains a Pixel Perfect / Nudger panel for the movable element under the cursor. Move it by 1, 5 or 10 physical pixels, read its centre coordinates, centre either axis or restore its default position; protected frames are left untouched in combat.",
    ["wn_401_layout_mirror"]      = "New — Player and Target mirroring keeps both unit frames horizontally symmetric around the physical screen centre and at the same height. Enabling it aligns Target from Player immediately, and later saves to either frame update the other without recursion.",
    ["wn_401_layout_unitframes"]  = "Changed — Player, Target and Focus frame positions now save and restore through the shared Layout V4 engine instead of a separate absolute-coordinate path. This gives them resolution-aware scaling, Pixel Perfect snapping and linked-anchor notifications while retaining compatibility fallbacks.",
    ["wn_401_layout_font_symbols"] = "Fixed — The Pixel Perfect / Nudger panel now uses font-safe plain-text direction markers, Player/Target labels and unavailable-coordinate placeholders. WoW fonts that lack the previous Unicode symbols no longer display missing-glyph diamonds.",
    ["wn_401_tomolayout_selection"] = "Changed — The precision-placement panel is now named TomoLayout and stays hidden until you click or begin dragging a supported mover. Selection hooks use dedicated mover overlays when available, so protected unit buttons are not modified.",
    ["wn_401_tomolayout_config"] = "Changed — TomoLayout now carries the contextual Configure button for the selected element. The former always-running mouse-focus scanner and floating cog are stopped, eliminating a full-time Layout Mode polling loop.",
    ["wn_401_tomolayout_highlight"] = "New — The selected mover is outlined in teal with a faint fill. Its border and gap remain two physical pixels at every UI scale, follow the frame while it moves and disappear when the selection ends, the frame is hidden or Layout Mode closes.",
    ["wn_401_azure_identity"]     = "Changed — TomoMod's visual identity is unified around azure #2E9DD8 throughout the core, modules, options and load-on-demand companions. The shared palette defines normal, hover and pressed accents plus subtly blue dark surfaces, while semantic success, warning, error, class and item-quality colours remain independent.",
    ["wn_401_azure_movers"]       = "Changed — Layout Mode mover overlays now share an opaque azure-to-near-white gradient, a high-contrast border and centred dark-azure text with a light shadow. The inner name band is gone, so compact movers no longer look like a box inside a box, and repeated styling calls do not stack textures.",
    ["wn_401_azure_mover_labels"] = "Fixed — Boss Frames, Class Reminder, the Consumable Bar and the Objective Tracker now reuse the shared mover label instead of drawing overlapping text. Objective Tracker scale changes update that localized label, and the Bags mover uses its existing translated name.",
    ["wn_401_azure_mover_coverage"] = "Changed — The shared mover renderer now also covers the Compass, Cooldown Manager holders, Frame Anchors, Minimap, player Cast Bar and Totem Bar. Their existing drag and save behaviour remains unchanged, while obsolete local backgrounds, borders and duplicate labels have been removed.",
    ["wn_401_azure_guard"]        = "Internal — The brand identity bench scans more than 100 Lua sources, verifies hexadecimal/RGB consistency, rejects retired mint and unexpected residual teal accents, checks ten migrated movers and fails if any of them recreates a duplicate label.",
})

TomoMod_RegisterLocale("frFR", {
    ["section_blizzard_auras"]   = "Cadres d'auras Blizzard",
    ["info_blizzard_auras"]      = "Contrôle les cadres Blizzard d'améliorations et d'affaiblissements sans toucher aux auras des cadres d'unité TomoMod. Les changements sont immédiats et ne demandent aucun rechargement.",
    ["opt_blizzard_auras_manage"] = "Laisser TomoMod gérer les cadres d'auras Blizzard",
    ["opt_blizzard_buffs"]       = "Afficher les améliorations Blizzard",
    ["opt_blizzard_debuffs"]     = "Afficher les affaiblissements Blizzard",
    ["layout_configure"]         = "Configurer cet élément",
    ["wn_401_layout_cogs"]       = "Nouveau — Le mode Layout affiche désormais un bouton engrenage au survol d'un élément déplaçable. Un clic ouvre directement la page d'options TomoMod correspondante.",
    ["wn_401_blizzard_auras"]    = "Nouveau — Interface > Général permet désormais de masquer séparément les cadres Blizzard d'améliorations et d'affaiblissements, à chaud et sans rechargement.",
    ["wn_401_chat_v4"]           = "Nouveau — Chat V4 reconstruit la présentation du chat avec une interface TomoMod sombre pour les messages, les onglets ancrés, la zone de saisie native et une nouvelle barre latérale, tandis que Blizzard reste responsable de l'acheminement, du formatage et des interactions sécurisées.",
    ["wn_401_chat_options"]      = "Nouveau — Skins > Fenêtre de chat devient le centre de contrôle en direct de Chat V4. Activez-le, réglez l'opacité du fond et la taille du texte, choisissez le comportement des messages, personnalisez la barre latérale et fixez la limite de lignes de la copie du chat : tout s'applique immédiatement, sans rechargement.",
    ["wn_401_chat_message_opacity"] = "Nouveau — L'opacité du cadre et celle de la zone des messages sont maintenant séparées. Le second curseur ne modifie que le fond derrière le texte du chat, jusqu'à une transparence totale, sans estomper les onglets, la barre latérale ni la zone de saisie ; les profils existants conservent leur apparence précédente.",
    ["wn_401_chat_messages"]     = "Nouveau — La présentation peut ajouter ou conserver les horodatages, abréger les noms de canaux traduits, s'estomper après deux minutes, transformer les smileys courants en symboles et colorer par classe les mentions de joueurs connus. Modifier une option reconstruit les lignes existantes pour garder tout l'historique visible cohérent.",
    ["wn_401_chat_urls"]         = "Nouveau — Les adresses HTTP(S) et www ordinaires deviennent des liens turquoise cliquables sans perturber les liens Blizzard existants. Un clic ouvre une fenêtre Ctrl+C ciblée et la ponctuation de fin de phrase reste hors du lien.",
    ["wn_401_chat_sidebar_options"] = "Nouveau — Placez la barre latérale à gauche ou à droite, réglez sa largeur, la taille et l'espacement des boutons, affichez ou masquez chaque raccourci et choisissez entre 50 et 1 000 lignes pour la copie du chat. Les anciens réglages de messages du Chat Skin migrent une seule fois vers Chat V4.",
    ["wn_401_chat_wiring"]       = "Modifié — Chat V4 est désormais l'unique module de chat public dans les valeurs par défaut, le registre des modules, l'accueil, l'installateur, les préréglages, les imports de profils et l'adaptation à la résolution. Les anciennes bases de données du chat ne servent plus qu'à la migration interne.",
    ["wn_401_chat_combatlog"]    = "Modifié — Le journal de combat utilise désormais la surface Chat V4 lorsqu'il est sélectionné, tandis que Blizzard filtre et formate toujours chaque ligne en premier. TomoMod reflète uniquement le résultat final et ne remplace jamais les API du journal de combat.",
    ["wn_401_chat_journal_controls"] = "Nouveau — La barre de filtres rapides du journal de combat Blizzard s'ancre désormais en haut de la zone de messages Chat V4, qui lui réserve sa place. Elle se masque sur les autres onglets et retrouve exactement sa position et sa visibilité d'origine lorsque Chat V4 est désactivé, sans être rattachée à un autre cadre ni remplacer les filtres.",
    ["wn_401_chat_phase21_polish"] = "Modifié — Les onglets reflétés restent maintenant dans la bordure supérieure du panneau. Le raccourci Emotes est retiré de la barre latérale et des options, y compris des dispositions enregistrées, tandis que Copie du chat, Butin, Réglages et Dernier message sont proprement regroupés par deux.",
    ["wn_401_chat_tabs"]         = "Nouveau — Les onglets Chat V4 sont maintenant des contrôles interactifs disposés de gauche à droite dans leur propre barre, y compris pour un journal de combat détaché. Les clics gauche et droit sont relayés vers l'onglet Blizzard invisible, préservant la sélection et les menus contextuels natifs tout en synchronisant le soulignement actif et les messages non lus.",
    ["wn_401_chat_native_chrome"] = "Corrigé — Les fonds, bordures NineSlice et poignées de redimensionnement du chat natif restent masqués même après avoir sélectionné Général ou Journal. Chat V4 mémorise l'alpha original de chaque élément et le restaure exactement à la désactivation.",
    ["wn_401_chat_sidebar"]      = "Nouveau — La barre latérale repensée ajoute des icônes personnalisées et des couleurs d'état dynamiques pour les amis, la guilde, En ligne/ABS/NPD, la voix, le micro et le mode sourd, ainsi que les compteurs en ligne et des raccourcis vers la copie du chat, le navigateur de butin, les réglages TomoMod et le dernier message.",
    ["wn_401_chat_sidebar_assets"] = "Modifié — Les icônes de la barre latérale utilisent désormais des textures transparentes 64×64 dédiées et remplaçables, avec des variantes pour le statut, le micro et le mode sourd. Les titres et descriptions des dix infobulles, ainsi que le menu En ligne/Absent/Ne pas déranger, sont traduits dans les six langues prises en charge.",
    ["wn_401_chat_copy"]         = "Nouveau — La copie du chat retrouve une fenêtre TomoMod complète : elle lit en direct l'onglet Blizzard actif à l'ouverture, peut être déplacée et redimensionnée, suit la taille de police du chat et propose des boutons Tout sélectionner/Fermer traduits, avec une barre de défilement moderne et un repli compatible.",
    ["wn_401_chat_copy_clean"]   = "Modifié — Le chat copié devient un texte lisible tout en conservant les couleurs des messages, les marqueurs de raid, les libellés des liens et les noms Battle.net disponibles. Les éléments graphiques et codes de contrôle sont retirés, les valeurs protégées ignorées, les textes courts sélectionnés automatiquement et la vue s'ouvre sur la ligne la plus récente.",
    ["wn_401_chat_safe"]         = "Modifié — Chat V4 reflète le chat Blizzard au lieu de remplacer son chemin sécurisé. Blizzard reste responsable du filtrage du journal de combat, aucune fonction FCF n'est accrochée et désactiver Chat V4 restaure la présentation native du chat.",
    ["wn_401_chat_links"]        = "Corrigé — Les noms de joueurs, les libellés de canaux, les liens d'objets et les autres hyperliens Blizzard sont de nouveau cliquables dans Chat V4. La zone des messages les transmet au gestionnaire natif de Blizzard, tandis que les liens web TomoMod ouvrent toujours la fenêtre de copie.",
    ["wn_401_chat_mover"]        = "Corrigé — Chat V4 possède désormais un véritable mover dans le mode Layout de TomoMod. Glisser sa surcouche couvrant tout le panneau déplace en direct le chat Blizzard et sa zone de saisie, sauvegarde la nouvelle position et libère temporairement la souris dans les modes Layout TomoMod et Édition Blizzard avant de restaurer les liens et le défilement.",
    ["wn_401_chat_community"]    = "Nouveau — Un onglet Communautaire traduit réunit les chuchotements reçus et envoyés, les messages privés Battle.net, la guilde et les officiers depuis toutes les fenêtres de chat Blizzard. Les doublons sont supprimés grâce à l'identifiant de ligne, tandis que les liens cliquables, l'état non lu, la saisie native et la copie du chat restent disponibles.",
    ["wn_401_objective_chrome"]  = "Corrigé — Le fond complet et les arrière-plans d'en-têtes animés du suivi des objectifs Blizzard ne peuvent plus réapparaître derrière TomoMod après une actualisation. Leurs valeurs d'alpha d'origine sont restaurées lorsque le suivi TomoMod est désactivé.",
    ["wn_401_castbar_lifecycle"]  = "Correctif — Votre barre d'incantation ne disparaît plus au milieu d'un sort long. Un sort instantané ou un proc déclenché pendant que vous incantiez fermait la barre du sort réellement en cours ; seule la vraie fin de cette incantation la ferme désormais.",
    ["wn_401_castbar_identity"]   = "Correctif — Une barre d'incantation ne réagit plus qu'à sa propre incantation. L'arrêt, l'échec ou l'interruption d'un autre sort ne peut plus la fermer ni la faire clignoter en rouge : chaque barre retient quelle incantation l'a ouverte et confronte chaque événement de fin à cette identité.",
    ["wn_401_castbar_stale"]      = "Nouveau — Une barre d'incantation qui n'a plus de nouvelles du serveur se referme une seconde après la fin prévue du sort. Un message perdu lors d'un pic de latence ou une reconnexion en pleine incantation pouvait laisser une barre figée à l'écran ; les sorts à charge sont épargnés, puisqu'ils sont censés se maintenir au-delà de leur fin annoncée jusqu'au relâchement.",
    ["wn_401_castbar_preview"]    = "Correctif — Le mode Layout et l'aperçu des options ne se disputent plus la barre d'incantation du joueur. Vous pouvez la déplacer depuis le mode Layout sans ouvrir la fenêtre d'options, fermer l'un n'annule plus l'autre, et l'entrée en combat referme immédiatement tout aperçu pour qu'il ne recouvre jamais une vraie incantation.",
    ["wn_401_layout_chat_route"]  = "Correctif — L'engrenage du mode Layout est de retour sur la fenêtre de chat. Il visait encore les cadres de l'ancien habillage du chat, remplacé par Chat V4 : survoler le panneau de chat n'offrait donc aucun raccourci vers ses réglages.",
    ["wn_401_bags_v4"]            = "Nouveau — Bags V4 remplace l'ancien habillage des sacs par une fenêtre entièrement gérée par TomoMod : tous les sacs dans une seule grille, le nombre d'emplacements occupés et disponibles dans l'en-tête, votre argent en pied de fenêtre, et un cadre que vous déplacez où vous voulez. Blizzard reste maître de toutes les actions sur les objets : clic, glisser-déposer, vente et infobulles fonctionnent exactement comme avant.",
    ["wn_401_bags_search_sort"]   = "Nouveau — Cherchez dans vos sacs au fil de la frappe, par nom d'objet ou par identifiant, et faites défiler l'affichage entre ordre des sacs, qualité, nom et niveau d'objet depuis le bouton d'en-tête. Le tri est purement visuel : aucun objet n'est jamais déplacé dans vos vrais sacs, il ne peut donc pas être interrompu en cours de route ni entrer en conflit avec le serveur.",
    ["wn_401_bags_sidebar"]       = "Nouveau — Une barre latérale garde sous les yeux vos objets épinglés et récents. Un clic milieu épingle n'importe quel objet et l'épingle reste attachée à votre profil ; tout nouvel objet arrivant dans vos sacs apparaît dans Récents. Un clic gauche sur une vignette retrouve l'objet dans la grille.",
    ["wn_401_bags_slots"]         = "Nouveau — Les emplacements affichent des bordures aux couleurs de qualité, le niveau d'objet sur les armes et les armures, une marque sur les objets épinglés et une icône grisée sur les objets verrouillés. Les quantités et les balayages de recharge viennent toujours du jeu lui-même, et les sacs à composants sont inclus quand le client les propose. Bordures, niveau d'objet et emplacements vides se désactivent séparément.",
    ["wn_401_bags_native"]        = "Modifié — L'ouverture et la fermeture suivent le jeu. Vos raccourcis de sacs, le micro-menu, les marchands, la boîte aux lettres et la banque ouvrent toujours la fenêtre, et les cadres de sacs Blizzard sont mis de côté tant que Bags V4 est actif, puis rendus intacts dès que vous le désactivez.",
    ["wn_401_bags_combat"]        = "Nouveau — Bags V4 ne crée ni ne déplace jamais un emplacement pendant un combat. Tout ce qui ne peut pas se faire sans risque est mis en attente et appliqué dès la fin du combat, tandis que les icônes, les quantités, les verrouillages et les recharges continuent de se mettre à jour.",
    ["wn_401_bags_migration"]     = "Modifié — Vos réglages de sacs existants sont repris une fois : opacité, échelle, taille des emplacements, espacement, nombre de colonnes, tri, bordures de qualité, niveau d'objet, emplacements vides, barre de recherche et position de la fenêtre. Le tableau de bord Accueil initialise et contrôle désormais directement Sacs V4 : le désactiver ferme la fenêtre personnalisée et restaure les sacs Blizzard, tandis que l'installateur et les préréglages restent synchronisés via l'ancien indicateur.",
    ["wn_401_bags_display_mode"]  = "Nouveau — Choisissez comment vos sacs s'ouvrent. Combiné garde tout dans l'unique fenêtre TomoMod ; Séparé les rend aux fenêtres individuelles de Blizzard et s'efface complètement, en remettant le réglage de sacs combinés du jeu à sa place.",
    ["wn_401_bags_options"]       = "Nouveau — Skins > Sacs est désormais une page de réglages vivante. Mode d'affichage, colonnes, taille et espacement des emplacements, échelle, opacité, tri visuel, barre de recherche, bordures de qualité, niveau d'objet, emplacements vides et nombre de vignettes épinglées et récentes : chaque réglage s'applique immédiatement, sans rechargement.",
    ["wn_401_bags_render"]        = "Correctif — Les emplacements utilisent désormais un rendu minimal indépendant des régions privées d'icône et de quantité de Blizzard : l'icône visible, la quantité et la recharge sont des calques TomoMod, tandis que le bouton d'objet natif conserve toutes les actions sécurisées. Les emplacements valides de Midnight ne peuvent ainsi plus paraître vides.",
    ["wn_401_bags_native_restore"] = "Modifié — Les régions privées d'icône et de quantité de Blizzard restent transparentes ; TomoMod dessine l'icône visible, la quantité et la recharge sur des calques simples et indépendants. Le contenu fixe sac/emplacement continue de s'actualiser en combat, tandis que seuls les changements de disposition attendent la fin du combat.",
    ["wn_401_bags_interactions"]  = "Correctif — Les emplacements conservent intacts les chemins sécurisés natifs de Blizzard pour les clics gauche/droit et le glisser. Les infobulles sont ajoutées par des hooks sans remplacer les scripts du modèle, le clic milieu est observé séparément pour l'épinglage et les calques visuels TomoMod restent non interactifs.",
    ["wn_401_bags_button_visibility"] = "Correctif — Chaque bouton d'objet sécurisé est explicitement affiché lors de sa création, de son rendu et de son placement dans la grille, empêchant un état masqué conservé par le pool de laisser un emplacement visible vide ou incapable de recevoir les clics.",
    ["wn_401_bags_empty_quality"] = "Modifié — Les emplacements vides utilisent un fond sombre minimal et une bordure douce, tandis que les bordures de qualité restent fortes au-dessus de la qualité commune et discrètes en dessous. Le niveau d'objet reste en haut à gauche sur son propre fond contrasté, loin de la quantité en bas à droite.",
    ["wn_401_bags_text_polish"]   = "Modifié — Les quantités et les niveaux d'objet s'adaptent à la taille choisie pour les emplacements et reposent sur de discrets fonds sombres. Les quantités restent en bas à droite et les niveaux en haut à gauche afin que les deux libellés ne se chevauchent plus.",
    ["wn_401_bags_surface_polish"] = "Modifié — Les surfaces, l'en-tête, la recherche, la barre latérale et le pied de Bags V4 sont légèrement plus clairs. Les messages vides Épinglés et Récents utilisent une couleur plus lisible, une largeur dynamique et jusqu'à deux lignes pour accueillir chaque traduction.",
    ["wn_401_bags_fit"]           = "Nouveau — La fenêtre combinée s'ajuste désormais au nombre réel d'objets affichés. Elle conserve le nombre de colonnes demandé si possible, ajoute des colonnes avant d'introduire une barre de défilement lorsque la hauteur manque, et ne permet le défilement que si aucune géométrie à l'écran ne peut contenir toute la grille ; une barre inutile reste masquée.",
    ["wn_401_bags_slot_identity"] = "Modifié — Les emplacements indiquent désormais leur fonction d'un coup d'œil : contour vert menthe/turquoise pour les sacs ordinaires et bleu azur pour le sac à composants. Les emplacements occupés conservent la couleur de qualité de l'objet lorsque les bordures de qualité sont activées ; sinon, ils gardent le contour de leur type de sac.",
    ["wn_401_mplus_score_columns"] = "Correctif — Les colonnes Score actuel, Score visé, Gain estimé et Potentiel du Planificateur de score se partagent désormais la largeur disponible au lieu d'utiliser des positions fixes. Potentiel ne dépasse plus du bord droit à la taille par défaut du Studio ni lorsque l'échelle du texte est augmentée.",
    ["wn_401_actionbar_negative_spacing"] = "Correctif — Les boutons d'action avec un espacement négatif ne superposent plus leurs zones cliquables. TomoMod partage les pixels communs en leur milieu : cliquer ou faire glisser un sort vise toujours le bouton sous le pointeur ; les espacements nuls ou positifs conservent toute leur zone de clic.",
    ["wn_401_raid_position"]      = "Correctif — La position des cadres de raid utilise désormais le moteur de disposition commun lors de l'enregistrement et de la restauration. Les anciens formats restent compatibles et les cadres déplacés ne sautent plus après un rechargement ou un changement de résolution ou d'échelle de l'interface.",
    ["wn_401_class_reminder_position"] = "Correctif — Le rappel de classe migre désormais son ancre enregistrée, l'adapte à la résolution actuelle et convertit les décalages selon sa propre échelle. Il ne dérive plus après un rechargement ou un changement d'affichage.",
    ["wn_401_objective_position"] = "Correctif — La position du suivi des objectifs comprend désormais les ancres héritées et celles de Layout V4, s'adapte depuis la résolution enregistrée et tient compte de l'échelle propre du cadre. Le suivi ne change plus d'ancre et ne dérive plus après un rechargement ou un changement d'affichage.",
    ["wn_401_layout_scaled_positions"] = "Correctif — Layout V4 enregistre désormais les décalages en unités UIParent et les reconvertit selon l'échelle effective de chaque cadre lors de la restauration. Les cadres redimensionnés ne multiplient plus leurs coordonnées et ne dérivent plus au fil des rechargements.",
    ["wn_401_layout_minimap"]     = "Correctif — Les coordonnées héritées particulières de la Minimap sont normalisées une seule fois vers Layout V4 sans la déplacer. La comparaison de la position physique ignore les réancrages internes inoffensifs de Blizzard, évitant les sauts et le décalage d'une image avec son habillage.",
    ["wn_401_layout_secondary_frames"] = "Modifié — La barre d'incantation du joueur, les barres de ressources et le compteur de résurrections de combat enregistrent et restaurent désormais leur position avec le moteur commun. Elles restent stables après un rechargement ou un changement de résolution ou d'échelle, avec leurs replis de compatibilité conservés.",
    ["wn_401_layout_mythic_tracker"] = "Correctif — Le suivi Mythique+ applique désormais son échelle avant sa position V4 et utilise le même moteur pour les déplacements, la réinitialisation et l'aperçu du mode Layout. Annuler son positionnement dans le Studio restaure la position complète au lieu de la ramener à l'ancien format.",
    ["wn_401_layout_v4_anchors"]  = "Nouveau — Chat V4 et Bags V4 déclarent désormais leurs véritables ancres déplaçables dans Layout V4. La migration des positions, les préréglages de résolution, l'estampillage des références et les imports sélectifs peuvent inclure les cadres actuels au lieu des anciennes ancres du chat.",
    ["wn_401_bags_position"]      = "Correctif — Bags V4 enregistre désormais la position physique de la fenêtre après un déplacement et la restaure avec Layout V4. Déplacer ou redimensionner les sacs ne réutilise plus les décalages précédant le glissement et ne fait plus dériver la fenêtre après les rechargements suivants.",
    ["wn_401_layout_v4_routes"]   = "Correctif — Les engrenages du mode Layout sur les barres d'action TUI et Bags V4 ouvrent désormais la bonne page Barres d'action ou Skins. Un contrôle automatisé vérifie aussi que chaque ancre déplaçable déclarée possède une route d'options active.",
    ["wn_401_layout_pixel_perfect"] = "Nouveau — Layout V4.1 peut aligner chaque position enregistrée par le moteur de disposition partagé sur le pixel physique le plus proche. Il calcule la taille réelle d'un pixel à partir de la résolution physique, reste facultatif et conserve le comportement V4 existant lorsqu'il est désactivé.",
    ["wn_401_layout_nudger"]      = "Nouveau — Le mode Layout reçoit un panneau Pixel Perfect / Nudger pour l'élément déplaçable survolé. Déplacez-le de 1, 5 ou 10 pixels physiques, consultez les coordonnées de son centre, centrez chaque axe ou restaurez sa position par défaut ; les cadres protégés restent intacts en combat.",
    ["wn_401_layout_mirror"]      = "Nouveau — La symétrie entre Joueur et Cible maintient les deux cadres d'unité en miroir horizontal autour du centre physique de l'écran et à la même hauteur. L'activer aligne immédiatement la Cible depuis le Joueur, puis chaque sauvegarde de l'un met à jour l'autre sans boucle.",
    ["wn_401_layout_unitframes"]  = "Modifié — Les positions des cadres Joueur, Cible et Focalisation sont désormais enregistrées et restaurées par le moteur Layout V4 partagé plutôt que par un chemin absolu séparé. Elles bénéficient ainsi de l'adaptation à la résolution, de l'alignement Pixel Perfect et des nouvelles notifications d'ancres liées, avec des replis compatibles.",
    ["wn_401_layout_font_symbols"] = "Correctif — Le panneau Pixel Perfect / Nudger utilise désormais des repères directionnels, des libellés Joueur/Cible et des coordonnées indisponibles en texte simple compatible avec les polices. Les polices WoW dépourvues des anciens symboles Unicode n'affichent plus de losanges de caractère manquant.",
    ["wn_401_tomolayout_selection"] = "Modifié — Le panneau de placement précis s'appelle désormais TomoLayout et reste masqué jusqu'à ce que vous cliquiez sur un élément déplaçable compatible ou commenciez à le déplacer. Les points d'accroche utilisent les superpositions de déplacement dédiées lorsqu'elles existent, sans modifier les boutons d'unité protégés.",
    ["wn_401_tomolayout_config"] = "Modifié — TomoLayout intègre désormais le bouton contextuel Configurer de l'élément sélectionné. L'ancien scanner permanent de la cible sous la souris et son engrenage flottant sont arrêtés, supprimant une boucle d'interrogation continue du mode Layout.",
    ["wn_401_tomolayout_highlight"] = "Nouveau — L'élément déplaçable sélectionné est entouré de turquoise avec un léger fond. La bordure et son espacement conservent deux pixels physiques à toute échelle, suivent le cadre pendant son déplacement et disparaissent avec la sélection, le cadre ou le mode Layout.",
    ["wn_401_azure_identity"]     = "Modifié — L'identité visuelle de TomoMod est de nouveau unifiée autour de l'azur #2E9DD8 dans le cœur, les modules, les options et les extensions chargées à la demande. La palette partagée définit l'accent normal, survolé et enfoncé ainsi que des surfaces sombres légèrement bleutées ; les couleurs fonctionnelles de réussite, d'avertissement, d'erreur, de classe et de qualité restent indépendantes.",
    ["wn_401_azure_movers"]       = "Modifié — Les superpositions du mode Layout partagent désormais un dégradé opaque de l'azur vers un blanc bleuté, une bordure très lisible et un texte azur foncé centré avec une ombre claire. Le bandeau intérieur a disparu : les petits movers ne ressemblent plus à une boîte dans une boîte et les appels répétés n'empilent pas de textures.",
    ["wn_401_azure_mover_labels"] = "Correctif — Les cadres de boss, le rappel de classe, la barre de consommables et le suivi d'objectifs réutilisent désormais le libellé commun au lieu de superposer du texte. Les changements d'échelle du suivi actualisent ce libellé localisé, et le mover des sacs utilise son nom déjà traduit.",
    ["wn_401_azure_mover_coverage"] = "Modifié — Le rendu commun des movers couvre maintenant aussi la boussole, les supports du gestionnaire de temps de recharge, les ancres de cadres, la minimap, la barre d'incantation du joueur et la barre de totems. Leur déplacement et leur sauvegarde restent inchangés, tandis que les anciens fonds, bordures et libellés en double ont été supprimés.",
    ["wn_401_azure_guard"]        = "Interne — Le banc de contrôle de l'identité parcourt plus de 100 sources Lua, vérifie la concordance hexadécimale/RVB, refuse l'ancienne menthe et les accents turquoise résiduels inattendus, contrôle dix movers migrés et échoue si l'un d'eux recrée un libellé en double.",
})

TomoMod_RegisterLocale("deDE", {
    ["section_blizzard_auras"]   = "Blizzard-Aurafenster",
    ["info_blizzard_auras"]      = "Steuert Blizzards standardmäßige Stärkungs- und Schwächungszauberfenster, ohne die Auren der TomoMod-Einheitenfenster zu beeinflussen. Änderungen gelten sofort und benötigen kein Neuladen.",
    ["opt_blizzard_auras_manage"] = "Blizzard-Aurafenster von TomoMod verwalten lassen",
    ["opt_blizzard_buffs"]       = "Blizzard-Stärkungszauber anzeigen",
    ["opt_blizzard_debuffs"]     = "Blizzard-Schwächungszauber anzeigen",
    ["layout_configure"]         = "Dieses Element konfigurieren",
    ["wn_401_layout_cogs"]       = "Neu — Im Layout-Modus erscheint beim Überfahren eines verschiebbaren Elements jetzt ein Zahnrad. Ein Klick öffnet direkt die passende TomoMod-Einstellungsseite.",
    ["wn_401_blizzard_auras"]    = "Neu — Unter Interface > Allgemein können Blizzards Buff- und Debuff-Fenster nun getrennt, live und ohne Neuladen ausgeblendet werden.",
    ["wn_401_chat_v4"]           = "Neu — Chat V4 baut die Chat-Darstellung mit einer dunklen TomoMod-Oberfläche für Nachrichten, angedockte Reiter, das native Eingabefeld und eine neue Seitenleiste neu auf, während Blizzard weiterhin Zustellung, Formatierung und sichere Interaktionen übernimmt.",
    ["wn_401_chat_options"]      = "Neu — Skins > Chatfenster ist jetzt die Live-Steuerzentrale für Chat V4. Aktivierung, Hintergrundtransparenz, Schriftgröße, Nachrichtenverhalten, Seitenleiste und Zeilenlimit der Chat-Kopie lassen sich dort einstellen; jede Änderung gilt sofort und ohne Neuladen.",
    ["wn_401_chat_message_opacity"] = "Neu — Die Deckkraft des Rahmens und des Nachrichtenbereichs sind jetzt getrennt. Der zweite Regler verändert nur den Hintergrund hinter dem Chattext bis hin zu vollständiger Transparenz, ohne Reiter, Seitenleiste oder Eingabefeld auszublenden; vorhandene Profile behalten ihr bisheriges Erscheinungsbild.",
    ["wn_401_chat_messages"]     = "Neu — Die Nachrichtendarstellung kann Zeitstempel ergänzen oder erhalten, lokalisierte Kanalnamen abkürzen, nach zwei Minuten ausblenden, bekannte Smileys in Symbole verwandeln und Erwähnungen bekannter Spieler in Klassenfarbe anzeigen. Eine Änderung baut vorhandene Zeilen neu auf, damit der gesamte sichtbare Verlauf einheitlich bleibt.",
    ["wn_401_chat_urls"]         = "Neu — Einfache HTTP(S)- und www-Adressen werden zu türkisen anklickbaren Links, ohne Blizzards vorhandene Hyperlinks zu verändern. Ein Klick öffnet ein fokussiertes Strg+C-Fenster; Satzzeichen am Satzende bleiben außerhalb des Links.",
    ["wn_401_chat_sidebar_options"] = "Neu — Die Seitenleiste kann links oder rechts stehen; Breite, Schaltflächengröße und Abstand sowie jeder einzelne Schnellzugriff sind einstellbar. Für die Chat-Kopie sind 50 bis 1.000 Zeilen wählbar. Vorhandene Nachrichtenoptionen des Chat-Skins werden einmalig zu Chat V4 migriert.",
    ["wn_401_chat_wiring"]       = "Geändert — Chat V4 ist jetzt in Standardwerten, Modulregister, Startseite, Installationsassistent, Voreinstellungen, Profilimporten und Auflösungsskalierung das einzige öffentliche Chatmodul. Die alten Chatdatenbanken dienen nur noch intern als Migrationsquellen.",
    ["wn_401_chat_combatlog"]    = "Geändert — Das Kampflog verwendet jetzt bei Auswahl die Chat-V4-Oberfläche, während Blizzard weiterhin jede Zeile zuerst filtert und formatiert. TomoMod spiegelt nur die endgültige Ausgabe und ersetzt niemals die Kampflog-APIs.",
    ["wn_401_chat_journal_controls"] = "Neu — Blizzards Schnellfilterleiste des Kampflogs ist jetzt oben im Chat-V4-Nachrichtenbereich angedockt, der dafür Platz reserviert. Auf anderen Reitern wird sie ausgeblendet und beim Deaktivieren von Chat V4 exakt an ihrer ursprünglichen Position und Sichtbarkeit wiederhergestellt, ohne sie einem anderen Frame unterzuordnen oder die Filter zu ersetzen.",
    ["wn_401_chat_phase21_polish"] = "Geändert — Gespiegelte Reiter bleiben jetzt innerhalb des oberen Panelrahmens. Der Emotes-Schnellzugriff wurde aus Seitenleiste, Optionen und gespeicherten Layouts entfernt; Chat-Kopie, Beute, Einstellungen und Neueste Nachricht sind sauber paarweise angeordnet.",
    ["wn_401_chat_tabs"]         = "Neu — Chat-V4-Reiter sind jetzt interaktive Steuerelemente, die in ihrer eigenen Leiste von links nach rechts angeordnet werden, einschließlich eines abgedockten Kampflogs. Links- und Rechtsklicks werden an den unsichtbaren Blizzard-Reiter weitergeleitet, sodass native Auswahl und Kontextmenüs erhalten bleiben und aktive Unterstreichung sowie Ungelesen-Anzeige synchron sind.",
    ["wn_401_chat_native_chrome"] = "Behoben — Native Chathintergründe, NineSlice-Rahmen und Größenänderungsgriffe bleiben auch nach Auswahl von Allgemein oder Kampflog ausgeblendet. Chat V4 speichert jeden ursprünglichen Alphawert und stellt ihn beim Deaktivieren exakt wieder her.",
    ["wn_401_chat_sidebar"]      = "Neu — Die überarbeitete Seitenleiste bietet eigene Symbole und Live-Statusfarben für Freunde, Gilde, Online/AFK/DND, Sprachchat, Stummschaltung und Taubschaltung sowie Online-Zähler und Schnellzugriffe auf Chat-Kopie, Beute-Browser, TomoMod-Einstellungen und die neueste Nachricht.",
    ["wn_401_chat_sidebar_assets"] = "Geändert — Die Symbole der Seitenleiste verwenden jetzt eigene austauschbare transparente 64×64-Texturen, einschließlich Varianten für Status, Mikrofon und Audio. Alle zehn Titel und Beschreibungen der Kurzinfos sowie das Menü Online/Abwesend/Bitte nicht stören sind in allen sechs unterstützten Sprachen übersetzt.",
    ["wn_401_chat_copy"]         = "Neu — Chat-Kopie ist wieder ein vollständiges TomoMod-Fenster: Es liest beim Öffnen den aktiven Blizzard-Reiter live, ist verschiebbar und skalierbar, folgt der Chat-Schriftgröße und bietet übersetzte Schaltflächen für Alles markieren und Schließen sowie eine moderne Bildlaufleiste mit kompatiblem Ersatz.",
    ["wn_401_chat_copy_clean"]   = "Geändert — Kopierter Chat wird zu lesbarem Text und behält Nachrichtenfarben, Schlachtzugsmarkierungen, Linkbeschriftungen und auflösbare Battle.net-Namen. UI-Grafiken und Steuercodes werden entfernt, geschützte Werte übersprungen, kürzere Texte automatisch markiert und die Ansicht öffnet bei der neuesten Zeile.",
    ["wn_401_chat_safe"]         = "Geändert — Chat V4 spiegelt Blizzards Chat, statt dessen sicheren Pfad zu ersetzen. Blizzard behält die Kontrolle über die Kampflog-Filterung, keine FCF-Funktion wird eingehakt und beim Deaktivieren von Chat V4 wird die native Chat-Darstellung wiederhergestellt.",
    ["wn_401_chat_links"]        = "Behoben — Spielernamen, Kanalbezeichnungen, Gegenstandslinks und andere Blizzard-Hyperlinks sind in Chat V4 wieder anklickbar. Die Nachrichtenfläche leitet sie an Blizzards native Linkverarbeitung weiter, während TomoMod-Weblinks weiterhin das Kopierfenster öffnen.",
    ["wn_401_chat_mover"]        = "Behoben — Chat V4 besitzt jetzt einen echten Verschieber im TomoMod-Layoutmodus. Ziehen an der vollflächigen Überlagerung bewegt den Blizzard-Chat und sein Eingabefeld live, speichert die neue Position und gibt die Maus im TomoMod-Layoutmodus sowie im Blizzard-Bearbeitungsmodus vorübergehend frei, bevor Links und Bildlauf wiederhergestellt werden.",
    ["wn_401_chat_community"]    = "Neu — Ein lokalisierter Gemeinschaft-Reiter bündelt ein- und ausgehende Charakterflüsternachrichten, private Battle.net-Nachrichten sowie Gilden- und Offizierschat aus allen Blizzard-Chatfenstern. Doppelte Zustellungen werden anhand der Zeilen-ID entfernt; anklickbare Links, Ungelesen-Status, native Texteingabe und Chat-Kopie bleiben verfügbar.",
    ["wn_401_objective_chrome"]  = "Behoben — Blizzards vollständiger Hintergrund und die animierten Kopfzeilen der Zielverfolgung können nach einer Aktualisierung nicht mehr hinter TomoMod erscheinen. Beim Deaktivieren der TomoMod-Zielverfolgung werden ihre ursprünglichen Alphawerte wiederhergestellt.",
    ["wn_401_castbar_lifecycle"]  = "Behoben — Eure Zauberleiste verschwindet nicht mehr mitten in einem langen Zauber. Ein Sofortzauber oder ein Proc, der während des Zauberns auslöste, schloss die Leiste des tatsächlich laufenden Zaubers; jetzt schließt sie nur noch dessen echtes Ende.",
    ["wn_401_castbar_identity"]   = "Behoben — Eine Zauberleiste reagiert nur noch auf ihren eigenen Zauber. Abbruch, Fehlschlag oder Unterbrechung eines anderen Zaubers kann sie weder schließen noch rot aufblitzen lassen, denn jede Leiste merkt sich, welcher Zauber sie geöffnet hat, und prüft jedes Endereignis dagegen.",
    ["wn_401_castbar_stale"]      = "Neu — Eine Zauberleiste, die nichts mehr vom Server hört, schließt sich eine Sekunde nach dem vorgesehenen Ende des Zaubers. Eine bei einem Latenzsprung verlorene Nachricht oder eine Neuverbindung mitten im Zauber konnte eine Leiste eingefroren auf dem Bildschirm zurücklassen; Entfesselungszauber sind ausgenommen, da sie bis zum Loslassen bewusst über ihr angekündigtes Ende hinaus bestehen bleiben.",
    ["wn_401_castbar_preview"]    = "Behoben — Layout-Modus und Optionsvorschau streiten nicht mehr um die Zauberleiste des Spielers. Ihr könnt sie im Layout-Modus verschieben, ohne das Optionsfenster zu öffnen, das Schließen des einen bricht das andere nicht mehr ab, und beim Betreten des Kampfes wird jede Vorschau sofort geschlossen, damit sie niemals über einem echten Zauber liegt.",
    ["wn_401_layout_chat_route"]  = "Behoben — Das Zahnrad des Layout-Modus ist im Chatfenster zurück. Es zeigte noch auf die Fenster des alten Chat-Skins, das Chat V4 ersetzt hat, sodass das Überfahren des Chatfensters keine Abkürzung zu dessen Einstellungen bot.",
    ["wn_401_bags_v4"]            = "Neu — Bags V4 ersetzt das alte Taschen-Skin durch ein Fenster, das vollständig TomoMod gehört: alle Taschen in einem Raster, die Zahl der belegten und gesamten Plätze in der Kopfzeile, euer Geld in der Fußzeile und ein Rahmen, den ihr frei verschieben könnt. Blizzard behält jede Gegenstandsaktion, also funktionieren Klicken, Ziehen, Verkaufen und Tooltips genau wie bisher.",
    ["wn_401_bags_search_sort"]   = "Neu — Durchsucht eure Taschen während des Tippens nach Gegenstandsnamen oder -ID und schaltet die Anzeige über die Kopfzeile zwischen Taschenreihenfolge, Qualität, Name und Gegenstandsstufe um. Die Sortierung ist rein visuell: In euren echten Taschen wird nichts verschoben, sie kann also nicht auf halbem Weg abbrechen und gerät nicht mit dem Server in Konflikt.",
    ["wn_401_bags_sidebar"]       = "Neu — Eine Seitenleiste hält angeheftete und neue Gegenstände im Blick. Ein Mittelklick heftet einen Gegenstand an, und die Anheftung bleibt an eurem Profil; alles, was neu in die Taschen kommt, erscheint unter Neu. Ein Linksklick auf eine Kachel findet den Gegenstand im Raster.",
    ["wn_401_bags_slots"]         = "Neu — Plätze zeigen qualitätsfarbene Ränder, die Gegenstandsstufe auf Waffen und Rüstung, eine Markierung auf angehefteten und ein abgedunkeltes Symbol auf gesperrten Gegenständen. Stapelzahlen und Abklingzeit-Animationen kommen weiterhin vom Spiel selbst, und Reagenzientaschen sind enthalten, sofern der Client sie kennt. Ränder, Gegenstandsstufe und leere Plätze lassen sich einzeln abschalten.",
    ["wn_401_bags_native"]        = "Geändert — Öffnen und Schließen folgt dem Spiel. Eure Taschen-Tastenbelegungen, das Mikromenü, Händler, der Briefkasten und die Bank öffnen weiterhin das Fenster, und Blizzards eigene Taschenfenster werden beiseitegestellt, solange Bags V4 aktiv ist, und unverändert zurückgegeben, sobald ihr es abschaltet.",
    ["wn_401_bags_combat"]        = "Neu — Bags V4 erstellt und verschiebt im Kampf niemals einen Platz. Was nicht sicher möglich ist, wird eingereiht und unmittelbar nach dem Kampf angewendet, während Symbole, Stapelzahlen, Sperren und Abklingzeiten durchgehend aktualisiert werden.",
    ["wn_401_bags_migration"]     = "Geändert — Eure vorhandenen Taschen-Einstellungen werden einmalig übernommen: Deckkraft, Skalierung, Platzgröße, Abstand, Spaltenzahl, Sortierung, Qualitätsränder, Gegenstandsstufe, leere Plätze, Suchleiste und Fensterposition. Die Startseite initialisiert und steuert Taschen V4 jetzt direkt: Beim Ausschalten wird das eigene Fenster geschlossen und Blizzards Taschen werden wiederhergestellt, während Installationsassistent und Voreinstellungen über den alten Schalter synchron bleiben.",
    ["wn_401_bags_display_mode"]  = "Neu — Wählt, wie eure Taschen sich öffnen. Kombiniert hält alles im einen TomoMod-Fenster; Getrennt gibt sie an Blizzards einzelne Taschenfenster zurück und tritt vollständig zur Seite, wobei die spieleigene Einstellung für kombinierte Taschen wieder ihren Platz einnimmt.",
    ["wn_401_bags_options"]       = "Neu — Skins > Taschen ist jetzt eine lebendige Einstellungsseite. Anzeigemodus, Spalten, Platzgröße und Abstand, Skalierung, Deckkraft, visuelle Sortierung, Suchleiste, Qualitätsränder, Gegenstandsstufe, leere Plätze und die Anzahl der angehefteten und neuen Kacheln — alles wird sofort und ohne Neuladen übernommen.",
    ["wn_401_bags_render"]        = "Behoben — Taschenplätze verwenden jetzt einen minimalen Renderer unabhängig von Blizzards privaten Symbol- und Zählregionen: sichtbares Symbol, Stapelzahl und Abklingzeit sind TomoMod-Ebenen, während der native Gegenstandsknopf alle sicheren Aktionen behält. Gültige Midnight-Plätze können dadurch nicht mehr leer erscheinen.",
    ["wn_401_bags_native_restore"] = "Geändert — Blizzards private Symbol- und Zählregionen bleiben transparent; TomoMod zeichnet sichtbares Symbol, Menge und Abklingzeit auf einfachen unabhängigen Ebenen. Feste Taschen-/Platzinhalte aktualisieren sich weiter im Kampf, nur Layoutänderungen warten bis zum Kampfende.",
    ["wn_401_bags_interactions"]  = "Behoben — Die nativen sicheren Pfade von Blizzard für Links-/Rechtsklick und Ziehen bleiben unverändert. Tooltips werden per Hook ergänzt, ohne die Skripte der Vorlage zu ersetzen; der Mittelklick wird separat zum Anheften beobachtet und TomoMods visuelle Overlays bleiben nicht interaktiv.",
    ["wn_401_bags_button_visibility"] = "Behoben — Jeder sichere Gegenstandsknopf wird beim Erstellen, Zeichnen und Platzieren im Raster ausdrücklich eingeblendet. Ein ausgeblendeter Pool-Zustand kann keinen sichtbaren Platz mehr leer oder nicht anklickbar lassen.",
    ["wn_401_bags_empty_quality"] = "Geändert — Leere Plätze verwenden eine minimale dunkle Fläche und einen weichen Rand; Qualitätsränder bleiben oberhalb gewöhnlicher Qualität kräftig und darunter dezent. Die Gegenstandsstufe steht oben links auf eigener Kontrastfläche, getrennt von der Stapelzahl unten rechts.",
    ["wn_401_bags_text_polish"]   = "Geändert — Stapelzahlen und Gegenstandsstufen skalieren mit der gewählten Platzgröße und liegen auf dezenten dunklen Flächen. Mengen bleiben unten rechts und Gegenstandsstufen oben links, sodass sich beide Beschriftungen nicht überlagern.",
    ["wn_401_bags_surface_polish"] = "Geändert — Oberfläche, Kopfzeile, Suche, Seitenleiste und Fußzeile von Bags V4 sind etwas heller. Leere Hinweise für Angeheftet und Neu verwenden klarere Farben, dynamische Breite und höchstens zwei umbrochene Zeilen, damit alle Übersetzungen passen.",
    ["wn_401_bags_fit"]           = "Neu — Das kombinierte Fenster passt sich jetzt an die tatsächliche Zahl der angezeigten Gegenstände an. Es behält die gewünschte Spaltenzahl wenn möglich bei, fügt bei knapper Höhe Spalten hinzu, bevor eine Bildlaufleiste nötig wird, und erlaubt Scrollen nur, wenn keine Geometrie auf dem Bildschirm das gesamte Raster aufnehmen kann; eine unnötige Leiste bleibt ausgeblendet.",
    ["wn_401_bags_slot_identity"] = "Geändert — Taschenplätze zeigen ihren Zweck jetzt auf einen Blick: normale Taschenplätze haben einen mint-/türkisfarbenen Rand, Reagenzientaschenplätze einen azurblau-weißen Rand. Belegte Plätze behalten bei aktivierten Qualitätsrändern die Farbe der Gegenstandsqualität; andernfalls bleibt der Rand ihres Taschentyps erhalten.",
    ["wn_401_mplus_score_columns"] = "Behoben — Die Spalten Aktuelle Punkte, Zielpunkte, Geschätzter Zuwachs und Potenzial des Punkteplaners teilen sich jetzt die verfügbare Kartenbreite, statt feste Positionen zu verwenden. Potenzial ragt bei der Standardgröße des Studios oder bei erhöhter Textskalierung nicht mehr über den rechten Rand hinaus.",
    ["wn_401_actionbar_negative_spacing"] = "Behoben — Aktionsknöpfe mit negativem Abstand überlagern ihre Klickflächen nicht mehr. TomoMod teilt die gemeinsamen Pixel in der Mitte, sodass Klicken oder Ziehen eines Zaubers immer den Knopf unter dem Mauszeiger trifft; bei Abstand null oder größer bleibt die vollständige Klickfläche erhalten.",
    ["wn_401_raid_position"]      = "Behoben — Positionen der Schlachtzugfenster verwenden beim Speichern und Wiederherstellen jetzt die gemeinsame Layout-Engine. Bestehende Positionsformate bleiben kompatibel und verschobene Fenster springen nach einem Neuladen oder einer Änderung von Auflösung oder UI-Skalierung nicht mehr.",
    ["wn_401_class_reminder_position"] = "Behoben — Die Klassenerinnerung migriert jetzt ihren gespeicherten Anker, skaliert ihn für die aktuelle Auflösung und rechnet Abstände mit ihrer eigenen Fensterskalierung um. Nach einem Neuladen oder einer Anzeigeänderung driftet sie nicht mehr.",
    ["wn_401_objective_position"] = "Behoben — Positionen der Zielverfolgung verstehen jetzt sowohl alte als auch Layout-V4-Anker, skalieren von der gespeicherten Auflösung um und berücksichtigen die eigene Skalierung des Fensters. Nach einem Neuladen oder einer Anzeigeänderung wechselt der Anker nicht mehr und das Fenster wandert nicht mehr.",
    ["wn_401_layout_scaled_positions"] = "Behoben — Layout V4 speichert Abstände jetzt in UIParent-Einheiten und rechnet sie beim Wiederherstellen durch die effektive Skalierung jedes Fensters zurück. Skalierte Fenster vervielfachen ihre Koordinaten nicht mehr und wandern nach wiederholtem Neuladen nicht mehr.",
    ["wn_401_layout_minimap"]     = "Behoben — Die besonderen alten Koordinaten der Minikarte werden einmalig ohne Verschiebung in Layout V4 normalisiert. Der Vergleich der physischen Position ignoriert harmlose interne Neupositionierungen von Blizzard und verhindert Sprünge sowie kurzzeitige Abweichungen von der umgebenden Oberfläche.",
    ["wn_401_layout_secondary_frames"] = "Geändert — Spieler-Zauberleiste, Ressourcenleisten und Kampfauferstehungszähler speichern und laden ihre Position jetzt über die gemeinsame Layout-Engine. Sie bleiben nach Neuladen sowie Änderungen von UI-Skalierung oder Auflösung stabil; Kompatibilitätsrückfälle bleiben erhalten.",
    ["wn_401_layout_mythic_tracker"] = "Behoben — Die Mythic+-Anzeige wendet ihre Skalierung jetzt vor der V4-Position an und verwendet dieselbe Engine für Verschieben, Zurücksetzen und Vorschauen im Layoutmodus. Ein Abbruch der Positionierung im Studio stellt die vollständige Position wieder her, statt sie ins alte Format zurückzustufen.",
    ["wn_401_layout_v4_anchors"]  = "Neu — Chat V4 und Bags V4 melden ihre tatsächlichen verschiebbaren Anker jetzt an Layout V4. Positionsmigration, Auflösungsvorgaben, Referenzmarkierung und selektive Importe können die aktuellen Fenster statt veralteter Chat-Anker einbeziehen.",
    ["wn_401_bags_position"]      = "Behoben — Bags V4 speichert nach dem Ziehen die physische Fensterposition und stellt sie über Layout V4 wieder her. Verschieben oder Skalieren verwendet keine alten Abstände von vor dem Ziehen mehr und lässt das Fenster nach späteren Neuladevorgängen nicht mehr wandern.",
    ["wn_401_layout_v4_routes"]   = "Behoben — Die Zahnräder des Layoutmodus auf TUI-Aktionsleisten und Bags V4 öffnen jetzt die richtige Seite für Aktionsleisten oder Skins. Eine automatische Prüfung stellt außerdem sicher, dass jeder deklarierte verschiebbare Anker eine aktive Optionsroute besitzt.",
    ["wn_401_layout_pixel_perfect"] = "Neu — Layout V4.1 kann jede über die gemeinsame Layout-Engine gespeicherte Position am nächsten physischen Bildschirmpixel ausrichten. Die tatsächliche Pixelgröße wird aus der physischen Auflösung ermittelt; die Funktion bleibt optional und ändert bei Deaktivierung das bisherige V4-Verhalten nicht.",
    ["wn_401_layout_nudger"]      = "Neu — Der Layoutmodus erhält ein Pixel-Perfect-/Nudger-Fenster für das gerade ausgewählte verschiebbare Element. Verschiebe es um 1, 5 oder 10 physische Pixel, lies seine Mittelpunktkoordinaten ab, zentriere eine Achse oder stelle die Standardposition wieder her; geschützte Frames bleiben im Kampf unangetastet.",
    ["wn_401_layout_mirror"]      = "Neu — Die Spiegelung von Spieler und Ziel hält beide Einheitenfenster horizontal symmetrisch zur physischen Bildschirmmitte und auf gleicher Höhe. Beim Aktivieren wird das Ziel sofort am Spieler ausgerichtet; spätere Speicherungen eines Frames aktualisieren den anderen ohne Rekursion.",
    ["wn_401_layout_unitframes"]  = "Geändert — Die Positionen der Spieler-, Ziel- und Fokusfenster werden jetzt über die gemeinsame Layout-V4-Engine gespeichert und wiederhergestellt statt über einen eigenen absoluten Koordinatenpfad. Dadurch erhalten sie auflösungsabhängige Skalierung, Pixel-Perfect-Ausrichtung und Benachrichtigungen für verknüpfte Anker, mit kompatiblen Rückfällen.",
    ["wn_401_layout_font_symbols"] = "Behoben — Das Pixel-Perfect-/Nudger-Fenster verwendet jetzt schriftsichere Richtungszeichen, Spieler/Ziel-Beschriftungen und Platzhalter für nicht verfügbare Koordinaten als Klartext. WoW-Schriftarten ohne die bisherigen Unicode-Symbole zeigen keine Platzhalter-Rauten mehr an.",
    ["wn_401_tomolayout_selection"] = "Geändert — Das Präzisionsfenster heißt jetzt TomoLayout und bleibt verborgen, bis du einen unterstützten Verschieber anklickst oder zu ziehen beginnst. Auswahl-Hooks nutzen vorhandene dedizierte Verschiebe-Overlays, sodass geschützte Einheiten-Schaltflächen unverändert bleiben.",
    ["wn_401_tomolayout_config"] = "Geändert — TomoLayout enthält jetzt die kontextbezogene Schaltfläche Konfigurieren für das ausgewählte Element. Der frühere ständig laufende Mausfokus-Scanner samt schwebendem Zahnrad bleibt ausgeschaltet, wodurch die dauerhafte Abfrageschleife im Layoutmodus entfällt.",
    ["wn_401_tomolayout_highlight"] = "Neu — Der ausgewählte Verschieber erhält eine türkisfarbene Kontur mit dezenter Füllung. Rand und Abstand bleiben bei jeder UI-Skalierung zwei physische Pixel breit, folgen dem Fenster beim Verschieben und verschwinden mit Auswahl, Fenster oder Layoutmodus.",
    ["wn_401_azure_identity"]     = "Geändert — TomoMods visuelle Identität ist im Kern, in Modulen, Optionen und bei Bedarf geladenen Begleit-Add-ons wieder einheitlich auf Azurblau #2E9DD8 ausgerichtet. Die gemeinsame Palette definiert normale, Hover- und gedrückte Akzente sowie leicht bläuliche dunkle Flächen; funktionale Erfolgs-, Warn-, Fehler-, Klassen- und Qualitätsfarben bleiben unabhängig.",
    ["wn_401_azure_movers"]       = "Geändert — Die Overlays des Layoutmodus verwenden jetzt einen deckenden Verlauf von Azurblau zu fast Weiß, einen kontrastreichen Rand und zentrierten dunkelblauen Text mit hellem Schatten. Das innere Namensband ist entfernt, damit kompakte Verschieber nicht mehr wie eine Schachtel in der Schachtel wirken; wiederholte Aufrufe stapeln keine Texturen.",
    ["wn_401_azure_mover_labels"] = "Behoben — Bossfenster, Klassenerinnerung, Verbrauchsleiste und Zielverfolgung verwenden jetzt das gemeinsame Verschieber-Label, statt Text übereinanderzuzeichnen. Skalierungsänderungen der Zielverfolgung aktualisieren dieses lokalisierte Label, und der Taschen-Verschieber nutzt seinen bereits übersetzten Namen.",
    ["wn_401_azure_mover_coverage"] = "Geändert — Der gemeinsame Verschieber-Renderer umfasst jetzt auch Kompass, Halter des Abklingzeit-Managers, Fensteranker, Minimap, Spieler-Zauberleiste und Totemleiste. Ihr bisheriges Verschiebe- und Speicherverhalten bleibt unverändert; veraltete lokale Hintergründe, Ränder und doppelte Beschriftungen wurden entfernt.",
    ["wn_401_azure_guard"]        = "Intern — Der Markendesign-Test durchsucht mehr als 100 Lua-Quellen, prüft Hex-/RGB-Konsistenz, weist das frühere Mintgrün und unerwartete verbliebene Türkisakzente zurück, kontrolliert zehn migrierte Verschieber und schlägt fehl, wenn einer davon ein doppeltes Label erzeugt.",
})

TomoMod_RegisterLocale("esES", {
    ["section_blizzard_auras"]   = "Marcos de auras de Blizzard",
    ["info_blizzard_auras"]      = "Controla los marcos predeterminados de beneficios y perjuicios de Blizzard sin afectar a las auras de los marcos de unidad de TomoMod. Los cambios se aplican al instante y no requieren recargar.",
    ["opt_blizzard_auras_manage"] = "Permitir que TomoMod gestione los marcos de auras de Blizzard",
    ["opt_blizzard_buffs"]       = "Mostrar beneficios de Blizzard",
    ["opt_blizzard_debuffs"]     = "Mostrar perjuicios de Blizzard",
    ["layout_configure"]         = "Configurar este elemento",
    ["wn_401_layout_cogs"]       = "Nuevo — El modo Layout muestra ahora un engranaje al pasar el cursor sobre un elemento movible. Un clic abre directamente la página de opciones de TomoMod correspondiente.",
    ["wn_401_blizzard_auras"]    = "Nuevo — Interface > General permite ocultar por separado los marcos de beneficios y perjuicios de Blizzard, en vivo y sin recargar.",
    ["wn_401_chat_v4"]           = "Nuevo — Chat V4 reconstruye la presentación del chat con una interfaz oscura de TomoMod para los mensajes, las pestañas acopladas, el cuadro de entrada nativo y una nueva barra lateral, mientras Blizzard sigue gestionando la entrega, el formato y las interacciones seguras.",
    ["wn_401_chat_options"]      = "Nuevo — Skins > Ventana de chat es ahora el centro de control en vivo de Chat V4. Actívalo, ajusta la opacidad del fondo y el tamaño de letra, elige el comportamiento de los mensajes, personaliza la barra lateral y fija el límite de líneas de Copiar chat; cada cambio se aplica al instante y sin recargar.",
    ["wn_401_chat_message_opacity"] = "Nuevo — La opacidad del marco y la del área de mensajes ahora son independientes. El segundo control solo cambia el fondo detrás del texto del chat, hasta dejarlo totalmente transparente, sin atenuar las pestañas, la barra lateral ni el cuadro de entrada; los perfiles existentes conservan su aspecto anterior.",
    ["wn_401_chat_messages"]     = "Nuevo — La presentación puede añadir o conservar marcas de tiempo, abreviar nombres de canales localizados, desvanecerse tras dos minutos, convertir emoticonos habituales en símbolos y colorear por clase las menciones de jugadores conocidos. Cambiar una opción reconstruye las líneas existentes para mantener uniforme todo el historial visible.",
    ["wn_401_chat_urls"]         = "Nuevo — Las direcciones HTTP(S) y www normales se convierten en enlaces turquesa sin alterar los hipervínculos existentes de Blizzard. Al pulsar se abre una ventana enfocada para Ctrl+C y la puntuación final queda fuera del enlace.",
    ["wn_401_chat_sidebar_options"] = "Nuevo — Coloca la barra lateral a la izquierda o derecha, ajusta su anchura, tamaño y separación de botones, muestra u oculta cada acceso y elige entre 50 y 1.000 líneas para Copiar chat. Los ajustes anteriores de mensajes de Chat Skin se migran una sola vez a Chat V4.",
    ["wn_401_chat_wiring"]       = "Cambio — Chat V4 es ahora el único módulo público de chat en los valores predeterminados, el registro de módulos, el panel de inicio, el instalador, los ajustes predefinidos, las importaciones de perfiles y el escalado por resolución. Las bases de datos antiguas del chat solo se conservan como fuentes internas de migración.",
    ["wn_401_chat_combatlog"]    = "Cambio — El registro de combate usa ahora la superficie de Chat V4 cuando se selecciona, mientras Blizzard sigue filtrando y formateando primero cada línea. TomoMod solo refleja la salida final y nunca sustituye las API del registro de combate.",
    ["wn_401_chat_journal_controls"] = "Nuevo — La barra de filtros rápidos del registro de combate de Blizzard se acopla ahora en la parte superior del área de mensajes de Chat V4, que reserva espacio para ella. Se oculta en otras pestañas y recupera exactamente su posición y visibilidad originales al desactivar Chat V4, sin vincularla a otro marco ni sustituir los filtros.",
    ["wn_401_chat_phase21_polish"] = "Cambio — Las pestañas reflejadas permanecen ahora dentro del borde superior del panel. El acceso Emotes se elimina de la barra lateral, las opciones y los diseños guardados; Copiar chat, Botín, Ajustes y Último mensaje quedan ordenados limpiamente por parejas.",
    ["wn_401_chat_tabs"]         = "Nuevo — Las pestañas de Chat V4 son ahora controles interactivos ordenados de izquierda a derecha en su propia barra, incluido un registro de combate desacoplado. Los clics izquierdo y derecho se reenvían a la pestaña invisible de Blizzard, conservando la selección y los menús contextuales nativos mientras se sincronizan el subrayado activo y los mensajes sin leer.",
    ["wn_401_chat_native_chrome"] = "Corregido — Los fondos, bordes NineSlice y controles de tamaño del chat nativo permanecen ocultos incluso después de seleccionar General o Registro de combate. Chat V4 guarda el alfa original de cada elemento y lo restaura exactamente al desactivarse.",
    ["wn_401_chat_sidebar"]      = "Nuevo — La barra lateral rediseñada añade iconos personalizados y colores de estado en vivo para Amigos, Hermandad, En línea/AUS/NM, voz, silenciar micrófono y ensordecer, además de contadores conectados y accesos a copia del chat, buscador de botín, ajustes de TomoMod y último mensaje.",
    ["wn_401_chat_sidebar_assets"] = "Cambio — Los iconos de la barra lateral usan ahora texturas transparentes de 64×64 dedicadas y reemplazables, con variantes para estado, micrófono y audio. Los títulos y descripciones de las diez ayudas, además del menú En línea/Ausente/No molestar, están traducidos a los seis idiomas compatibles.",
    ["wn_401_chat_copy"]         = "Nuevo — Copiar chat vuelve como una ventana completa de TomoMod: lee en vivo la pestaña activa de Blizzard al abrirse, se puede mover y redimensionar, sigue el tamaño de letra del chat y ofrece botones traducidos para Seleccionar todo y Cerrar, con una barra de desplazamiento moderna y una alternativa compatible.",
    ["wn_401_chat_copy_clean"]   = "Cambio — El chat copiado se convierte en texto legible y conserva los colores de los mensajes, los marcadores de banda, las etiquetas de los enlaces y los nombres de Battle.net disponibles. Se eliminan los gráficos y códigos de control, se omiten los valores protegidos, los textos cortos se seleccionan automáticamente y la vista se abre en la línea más reciente.",
    ["wn_401_chat_safe"]         = "Cambio — Chat V4 refleja el chat de Blizzard en lugar de sustituir su ruta segura. Blizzard conserva el control del filtrado del registro de combate, no se engancha ninguna función FCF y al desactivar Chat V4 se restaura la presentación nativa.",
    ["wn_401_chat_links"]        = "Corregido — Los nombres de jugadores, las etiquetas de canales, los enlaces de objetos y los demás hipervínculos de Blizzard vuelven a ser interactivos en Chat V4. El área de mensajes los reenvía al controlador nativo de Blizzard, mientras los enlaces web de TomoMod siguen abriendo la ventana de copia.",
    ["wn_401_chat_mover"]        = "Corregido — Chat V4 dispone ahora de un auténtico control de movimiento en el modo Layout de TomoMod. Arrastrar su superposición de panel completo mueve en vivo el chat de Blizzard y su cuadro de entrada, guarda la nueva posición y libera temporalmente el ratón en los modos Layout de TomoMod y Edición de Blizzard antes de restaurar enlaces y desplazamiento.",
    ["wn_401_chat_community"]    = "Nuevo — Una pestaña Comunidad localizada reúne los susurros de personaje recibidos y enviados, los mensajes privados de Battle.net y los chats de hermandad y oficiales de todas las ventanas de chat de Blizzard. Los duplicados se eliminan por ID de línea; los enlaces interactivos, el estado sin leer, la entrada nativa y Copiar chat siguen disponibles.",
    ["wn_401_objective_chrome"]  = "Corregido — El fondo completo y los fondos animados de los encabezados del seguimiento de objetivos de Blizzard ya no pueden reaparecer detrás de TomoMod tras una actualización. Sus valores alfa originales se restauran al desactivar el seguimiento de TomoMod.",
    ["wn_401_castbar_lifecycle"]  = "Corrección — Tu barra de lanzamiento ya no desaparece a mitad de un hechizo largo. Un hechizo instantáneo o un proc que saltaba mientras lanzabas cerraba la barra del hechizo que estabas lanzando de verdad; ahora solo la cierra el final real de ese lanzamiento.",
    ["wn_401_castbar_identity"]   = "Corrección — Una barra de lanzamiento solo reacciona ya a su propio lanzamiento. La parada, el fallo o la interrupción de otro hechizo no puede cerrarla ni hacerla parpadear en rojo, porque cada barra recuerda qué lanzamiento la abrió y contrasta con él cada evento de cierre.",
    ["wn_401_castbar_stale"]      = "Nuevo — Una barra de lanzamiento que deja de recibir noticias del servidor se cierra un segundo después del final previsto del hechizo. Un mensaje perdido en un pico de latencia o una reconexión a mitad de lanzamiento podía dejar una barra congelada en pantalla; los hechizos de intensificación quedan al margen, ya que están pensados para mantenerse más allá de su final anunciado hasta que los sueltas.",
    ["wn_401_castbar_preview"]    = "Corrección — El modo Diseño y la vista previa de opciones ya no se disputan la barra de lanzamiento del jugador. Puedes moverla desde el modo Diseño sin abrir la ventana de opciones, cerrar una ya no cancela la otra, y entrar en combate cierra al instante cualquier vista previa para que nunca se superponga a un lanzamiento real.",
    ["wn_401_layout_chat_route"]  = "Corrección — El engranaje del modo Diseño vuelve a estar en la ventana de chat. Seguía apuntando a los marcos del antiguo skin de chat, sustituido por Chat V4, así que pasar el ratón por el panel de chat no ofrecía ningún acceso a sus ajustes.",
    ["wn_401_bags_v4"]            = "Nuevo — Bags V4 sustituye el antiguo skin de bolsas por una ventana totalmente gestionada por TomoMod: todas las bolsas en una sola cuadrícula, el número de espacios ocupados y totales en la cabecera, tu dinero en el pie y un marco que puedes arrastrar donde quieras. Blizzard sigue a cargo de todas las acciones sobre objetos, así que hacer clic, arrastrar, vender y las descripciones funcionan igual que siempre.",
    ["wn_401_bags_search_sort"]   = "Nuevo — Busca en tus bolsas mientras escribes, por nombre de objeto o por identificador, y alterna la vista entre orden de bolsas, calidad, nombre y nivel de objeto desde el botón de la cabecera. La ordenación es puramente visual: nunca se mueve nada dentro de tus bolsas reales, así que no puede interrumpirse a medias ni entrar en conflicto con el servidor.",
    ["wn_401_bags_sidebar"]       = "Nuevo — Una barra lateral mantiene a la vista tus objetos fijados y recientes. Un clic central fija cualquier objeto y la fijación se guarda con tu perfil; todo lo que llega nuevo a tus bolsas aparece en Recientes. Un clic izquierdo en una miniatura localiza ese objeto en la cuadrícula.",
    ["wn_401_bags_slots"]         = "Nuevo — Los espacios muestran bordes con el color de la calidad, el nivel de objeto en armas y armaduras, una marca en los objetos fijados y un icono atenuado en los bloqueados. Las cantidades y los barridos de reutilización siguen viniendo del propio juego, y las bolsas de componentes se incluyen cuando el cliente las ofrece. Bordes, nivel de objeto y espacios vacíos se desactivan por separado.",
    ["wn_401_bags_native"]        = "Cambio — Abrir y cerrar sigue al juego. Tus atajos de bolsas, el micromenú, los vendedores, el buzón y el banco siguen abriendo la ventana, y los marcos de bolsas de Blizzard se apartan mientras Bags V4 está activo y se devuelven intactos en cuanto lo desactivas.",
    ["wn_401_bags_combat"]        = "Nuevo — Bags V4 nunca crea ni mueve un espacio mientras estás en combate. Todo lo que no puede hacerse con seguridad queda en cola y se aplica en cuanto termina la pelea, mientras los iconos, las cantidades, los bloqueos y las reutilizaciones siguen actualizándose.",
    ["wn_401_bags_migration"]     = "Cambio — Tus ajustes de bolsas existentes se trasladan una vez: opacidad, escala, tamaño de espacio, separación, número de columnas, ordenación, bordes de calidad, nivel de objeto, espacios vacíos, barra de búsqueda y posición de la ventana. El panel de Inicio ahora inicializa y controla directamente Bolsas V4: al desactivarlo se cierra la ventana personalizada y se restauran las bolsas de Blizzard, mientras el instalador y los ajustes predefinidos permanecen sincronizados mediante el indicador antiguo.",
    ["wn_401_bags_display_mode"]  = "Nuevo — Elige cómo se abren tus bolsas. Combinadas mantiene todo en la única ventana de TomoMod; Separadas las devuelve a las ventanas individuales de Blizzard y se aparta por completo, dejando el ajuste de bolsas combinadas del juego en su sitio.",
    ["wn_401_bags_options"]       = "Nuevo — Skins > Bolsas es ahora una página de ajustes en vivo. Modo de visualización, columnas, tamaño y separación de espacios, escala, opacidad, ordenación visual, barra de búsqueda, bordes de calidad, nivel de objeto, espacios vacíos y cuántas miniaturas fijadas y recientes guarda la barra lateral: todo se aplica al instante, sin recargar.",
    ["wn_401_bags_render"]        = "Corrección — Los espacios usan ahora un renderizador mínimo independiente de las regiones privadas de icono y cantidad de Blizzard: el icono visible, la cantidad y la reutilización son capas de TomoMod, mientras el botón de objeto nativo conserva todas las acciones seguras. Los espacios válidos de Midnight ya no pueden parecer vacíos.",
    ["wn_401_bags_native_restore"] = "Cambio — Las regiones privadas de icono y cantidad de Blizzard permanecen transparentes; TomoMod dibuja el icono visible, la cantidad y la reutilización en capas simples e independientes. El contenido fijo de bolsa/espacio sigue actualizándose en combate y solo los cambios de diseño esperan a que termine.",
    ["wn_401_bags_interactions"]  = "Corrección — Los espacios conservan intactas las rutas seguras nativas de Blizzard para clic izquierdo/derecho y arrastre. Las descripciones se añaden mediante hooks sin sustituir los scripts de la plantilla, el clic central se observa por separado para fijar objetos y las capas visuales de TomoMod siguen sin ser interactivas.",
    ["wn_401_bags_button_visibility"] = "Corrección — Cada botón de objeto seguro se muestra explícitamente al crearse, dibujarse y colocarse en la cuadrícula, evitando que un estado oculto del grupo deje un espacio visible vacío o incapaz de recibir clics.",
    ["wn_401_bags_empty_quality"] = "Cambio — Los espacios vacíos usan un relleno oscuro mínimo y un borde suave; los bordes de calidad siguen siendo fuertes por encima de la calidad común y discretos por debajo. El nivel de objeto queda arriba a la izquierda sobre su propio fondo de contraste, separado de la cantidad abajo a la derecha.",
    ["wn_401_bags_text_polish"]   = "Cambio — Las cantidades y los niveles de objeto se adaptan al tamaño de espacio elegido y descansan sobre fondos oscuros discretos. Las cantidades quedan abajo a la derecha y los niveles arriba a la izquierda para que ambas etiquetas no se superpongan.",
    ["wn_401_bags_surface_polish"] = "Cambio — Las superficies, cabecera, búsqueda, barra lateral y pie de Bags V4 son ligeramente más claros. Los mensajes vacíos de Fijados y Recientes usan un color más legible, anchura dinámica y hasta dos líneas para que todas las traducciones quepan.",
    ["wn_401_bags_fit"]           = "Nuevo — La ventana combinada se ajusta ahora al número real de objetos mostrados. Conserva el número de columnas solicitado cuando es posible, añade columnas antes de introducir una barra de desplazamiento si falta altura y solo permite desplazarse cuando ninguna geometría en pantalla puede contener toda la cuadrícula; las barras innecesarias permanecen ocultas.",
    ["wn_401_bags_slot_identity"] = "Modificado — Los espacios indican ahora su función de un vistazo: contorno verde menta/turquesa para las bolsas normales y azul celeste para la bolsa de componentes. Los espacios ocupados conservan el color de calidad del objeto cuando están activados los bordes de calidad; de lo contrario, mantienen el contorno de su tipo de bolsa.",
    ["wn_401_mplus_score_columns"] = "Corregido — Las columnas Puntuación actual, Puntuación objetivo, Ganancia estimada y Potencial del Planificador de puntuación comparten ahora el ancho disponible de la tarjeta en vez de utilizar posiciones fijas. Potencial ya no sobresale por el borde derecho con el tamaño predeterminado del Studio ni al aumentar la escala del texto.",
    ["wn_401_actionbar_negative_spacing"] = "Corregido — Los botones de acción con espaciado negativo ya no superponen sus zonas de clic. TomoMod divide los píxeles compartidos por la mitad, de modo que hacer clic o arrastrar un hechizo siempre apunta al botón bajo el puntero; el espaciado cero o positivo conserva toda la zona de clic.",
    ["wn_401_raid_position"]      = "Corregido — Las posiciones de los marcos de banda usan ahora el motor de diseño compartido al guardarse y restaurarse. Los formatos existentes siguen siendo compatibles y los marcos movidos ya no saltan tras recargar o cambiar la resolución o la escala de la interfaz.",
    ["wn_401_class_reminder_position"] = "Corregido — El recordatorio de clase migra ahora su ancla guardada, la adapta a la resolución actual y convierte los desplazamientos según su propia escala. Ya no se desvía tras recargar o cambiar la pantalla.",
    ["wn_401_objective_position"] = "Corregido — Las posiciones del seguimiento de objetivos entienden ahora tanto las anclas antiguas como las de Layout V4, se adaptan desde la resolución guardada y tienen en cuenta la escala propia del marco. Ya no cambia de ancla ni se desplaza por la pantalla tras recargar o cambiar la configuración de pantalla.",
    ["wn_401_layout_scaled_positions"] = "Corregido — Layout V4 guarda ahora los desplazamientos en unidades de UIParent y los reconvierte mediante la escala efectiva de cada marco al restaurarlos. Los marcos escalados ya no multiplican sus coordenadas ni se desplazan tras varias recargas.",
    ["wn_401_layout_minimap"]     = "Corregido — Las coordenadas antiguas especiales del minimapa se normalizan una sola vez en Layout V4 sin moverlo. La comparación de la posición física ignora los cambios de ancla internos e inofensivos de Blizzard, evitando saltos y desajustes momentáneos con su marco.",
    ["wn_401_layout_secondary_frames"] = "Modificado — La barra de lanzamiento del jugador, las barras de recursos y el contador de resurrecciones en combate guardan y restauran ahora su posición mediante el motor compartido. Permanecen estables tras recargar o cambiar la escala o resolución, conservando sus alternativas de compatibilidad.",
    ["wn_401_layout_mythic_tracker"] = "Corregido — El seguimiento de Míticas+ aplica ahora su escala antes de la posición V4 y usa el mismo motor para mover, restablecer y mostrar vistas previas del modo Layout. Cancelar la colocación en el Studio restaura la posición completa en vez de devolverla al formato antiguo.",
    ["wn_401_layout_v4_anchors"]  = "Nuevo — Chat V4 y Bags V4 declaran ahora sus anclas móviles reales en Layout V4. La migración de posiciones, los preajustes de resolución, el registro de referencias y las importaciones selectivas pueden incluir los marcos actuales en vez de las anclas antiguas del chat.",
    ["wn_401_bags_position"]      = "Corregido — Bags V4 guarda ahora la posición física de la ventana después de arrastrarla y la restaura mediante Layout V4. Mover o escalar las bolsas ya no reutiliza los desplazamientos previos al arrastre ni hace que la ventana se desplace tras recargas posteriores.",
    ["wn_401_layout_v4_routes"]   = "Corregido — Los engranajes del modo Layout en las barras de acción TUI y Bags V4 abren ahora la página correcta de Barras de acción o Skins. Una comprobación automática también garantiza que cada ancla móvil declarada tenga una ruta de opciones activa.",
    ["wn_401_layout_pixel_perfect"] = "Nuevo — Layout V4.1 puede alinear cada posición guardada por el motor de diseño compartido con el píxel físico más cercano. Calcula el tamaño real del píxel a partir de la resolución física, es opcional y mantiene sin cambios el comportamiento V4 existente cuando está desactivado.",
    ["wn_401_layout_nudger"]      = "Nuevo — El modo Layout incorpora un panel Pixel Perfect / Nudger para el elemento móvil seleccionado al pasar el cursor. Muévelo 1, 5 o 10 píxeles físicos, consulta las coordenadas de su centro, centra cualquiera de los ejes o restaura su posición predeterminada; los marcos protegidos no se modifican en combate.",
    ["wn_401_layout_mirror"]      = "Nuevo — La simetría entre Jugador y Objetivo mantiene ambos marcos de unidad reflejados horizontalmente respecto al centro físico de la pantalla y a la misma altura. Al activarla, Objetivo se alinea inmediatamente desde Jugador; después, guardar cualquiera actualiza el otro sin recursión.",
    ["wn_401_layout_unitframes"]  = "Cambio — Las posiciones de los marcos de Jugador, Objetivo y Foco ahora se guardan y restauran mediante el motor compartido Layout V4 en vez de una ruta independiente de coordenadas absolutas. Así reciben escalado según resolución, ajuste Pixel Perfect y avisos de anclas vinculadas, con alternativas compatibles.",
    ["wn_401_layout_font_symbols"] = "Corregido — El panel Pixel Perfect / Nudger usa ahora indicadores de dirección, etiquetas Jugador/Objetivo y marcadores de coordenadas no disponibles en texto simple compatible con las fuentes. Las fuentes de WoW que no incluyen los símbolos Unicode anteriores ya no muestran rombos de glifos ausentes.",
    ["wn_401_tomolayout_selection"] = "Cambio — El panel de colocación precisa se llama ahora TomoLayout y permanece oculto hasta que haces clic o empiezas a arrastrar un elemento móvil compatible. Los enlaces de selección usan las superposiciones de movimiento dedicadas cuando existen, sin modificar botones de unidad protegidos.",
    ["wn_401_tomolayout_config"] = "Cambio — TomoLayout incorpora ahora el botón contextual Configurar del elemento seleccionado. El antiguo escáner permanente del foco del ratón y su engranaje flotante quedan desactivados, eliminando un ciclo de consulta continuo del modo Layout.",
    ["wn_401_tomolayout_highlight"] = "Nuevo — El elemento móvil seleccionado se resalta con un contorno turquesa y un relleno tenue. El borde y la separación conservan dos píxeles físicos con cualquier escala de interfaz, siguen al marco mientras se mueve y desaparecen al terminar la selección, ocultarse el marco o cerrar el modo Layout.",
    ["wn_401_azure_identity"]     = "Cambio — La identidad visual de TomoMod vuelve a estar unificada en torno al azul celeste #2E9DD8 en el núcleo, los módulos, las opciones y los complementos bajo demanda. La paleta compartida define los acentos normal, al pasar el cursor y pulsado, además de superficies oscuras con un leve matiz azul; los colores funcionales de éxito, aviso, error, clase y calidad siguen siendo independientes.",
    ["wn_401_azure_movers"]       = "Cambio — Las superposiciones del modo Layout usan ahora un degradado opaco de azul celeste a casi blanco, un borde de alto contraste y texto azul oscuro centrado con una sombra clara. Se eliminó la banda interior del nombre para que los elementos compactos no parezcan una caja dentro de otra, y las llamadas repetidas no apilan texturas.",
    ["wn_401_azure_mover_labels"] = "Corregido — Los marcos de jefes, el recordatorio de clase, la barra de consumibles y el seguimiento de objetivos reutilizan ahora la etiqueta común en vez de superponer texto. Los cambios de escala del seguimiento actualizan esa etiqueta localizada, y el elemento móvil de las bolsas usa su nombre ya traducido.",
    ["wn_401_azure_mover_coverage"] = "Cambio — El renderizador común de elementos móviles incluye ahora también la brújula, los soportes del gestor de reutilización, las anclas de marcos, el minimapa, la barra de lanzamiento del jugador y la barra de tótems. Su comportamiento de arrastre y guardado no cambia, mientras que se eliminaron fondos, bordes y etiquetas duplicadas locales obsoletos.",
    ["wn_401_azure_guard"]        = "Interno — La prueba de identidad recorre más de 100 fuentes Lua, comprueba la coherencia hexadecimal/RGB, rechaza el anterior verde menta y acentos turquesa residuales inesperados, controla diez elementos móviles migrados y falla si alguno vuelve a crear una etiqueta duplicada.",
})

TomoMod_RegisterLocale("itIT", {
    ["section_blizzard_auras"]   = "Riquadri aure Blizzard",
    ["info_blizzard_auras"]      = "Controlla i riquadri predefiniti di benefici e penalità di Blizzard senza modificare le aure dei riquadri unità TomoMod. Le modifiche sono immediate e non richiedono un reload.",
    ["opt_blizzard_auras_manage"] = "Lascia che TomoMod gestisca i riquadri aure Blizzard",
    ["opt_blizzard_buffs"]       = "Mostra benefici Blizzard",
    ["opt_blizzard_debuffs"]     = "Mostra penalità Blizzard",
    ["layout_configure"]         = "Configura questo elemento",
    ["wn_401_layout_cogs"]       = "Novità — In modalità Layout compare ora un ingranaggio passando sopra un elemento spostabile. Un clic apre direttamente la relativa pagina delle opzioni TomoMod.",
    ["wn_401_blizzard_auras"]    = "Novità — Interface > Generale consente ora di nascondere separatamente i riquadri benefici e penalità di Blizzard, in tempo reale e senza reload.",
    ["wn_401_chat_v4"]           = "Novità — Chat V4 ricostruisce la presentazione della chat con un'interfaccia TomoMod scura per messaggi, schede ancorate, casella di immissione nativa e una nuova barra laterale, mentre Blizzard continua a gestire consegna, formattazione e interazioni protette.",
    ["wn_401_chat_options"]      = "Novità — Skin > Finestra chat è ora il centro di controllo live di Chat V4. Attivalo, regola opacità dello sfondo e dimensione del testo, scegli il comportamento dei messaggi, personalizza la barra laterale e imposta il limite di righe di Copia chat: ogni modifica si applica subito senza reload.",
    ["wn_401_chat_message_opacity"] = "Novità — L'opacità del riquadro e quella dell'area messaggi sono ora separate. Il secondo cursore modifica solo lo sfondo dietro il testo della chat, fino alla trasparenza completa, senza attenuare schede, barra laterale o casella di immissione; i profili esistenti mantengono l'aspetto precedente.",
    ["wn_401_chat_messages"]     = "Novità — La presentazione può aggiungere o mantenere gli orari, abbreviare i nomi localizzati dei canali, dissolversi dopo due minuti, trasformare le faccine comuni in simboli e colorare per classe le menzioni dei giocatori conosciuti. Cambiare un'opzione ricostruisce le righe esistenti per mantenere coerente tutta la cronologia visibile.",
    ["wn_401_chat_urls"]         = "Novità — I normali indirizzi HTTP(S) e www diventano collegamenti turchesi cliccabili senza alterare i collegamenti Blizzard esistenti. Un clic apre una finestra Ctrl+C focalizzata e la punteggiatura finale resta fuori dal collegamento.",
    ["wn_401_chat_sidebar_options"] = "Novità — Posiziona la barra laterale a sinistra o destra, regola larghezza, dimensione e spaziatura dei pulsanti, mostra o nasconde ogni scorciatoia e scegli da 50 a 1.000 righe per Copia chat. Le precedenti impostazioni dei messaggi di Chat Skin migrano una sola volta a Chat V4.",
    ["wn_401_chat_wiring"]       = "Modifica — Chat V4 è ora l'unico modulo chat pubblico nei valori predefiniti, nel registro moduli, nella pagina iniziale, nell'installazione, nei preset, nelle importazioni dei profili e nel ridimensionamento per risoluzione. I vecchi database della chat restano solo fonti interne di migrazione.",
    ["wn_401_chat_combatlog"]    = "Modifica — Il registro di combattimento usa ora la superficie Chat V4 quando viene selezionato, mentre Blizzard continua a filtrare e formattare prima ogni riga. TomoMod rispecchia solo l'output finale e non sostituisce mai le API del registro di combattimento.",
    ["wn_401_chat_journal_controls"] = "Novità — La barra dei filtri rapidi del registro di combattimento Blizzard è ora ancorata in alto nell'area messaggi di Chat V4, che le riserva spazio. Si nasconde nelle altre schede e torna esattamente alla posizione e visibilità originali quando Chat V4 viene disattivato, senza assegnarla a un altro riquadro né sostituire i filtri.",
    ["wn_401_chat_phase21_polish"] = "Modifica — Le schede rispecchiate restano ora entro il bordo superiore del pannello. La scorciatoia Emote è rimossa da barra laterale, opzioni e layout salvati; Copia chat, Bottino, Impostazioni e Ultimo messaggio sono ordinati in coppie.",
    ["wn_401_chat_tabs"]         = "Novità — Le schede Chat V4 sono ora controlli interattivi disposti da sinistra a destra nella propria barra, incluso un registro di combattimento sganciato. I clic sinistro e destro vengono inoltrati alla scheda Blizzard invisibile, mantenendo selezione e menu contestuali nativi e sincronizzando sottolineatura attiva e messaggi non letti.",
    ["wn_401_chat_native_chrome"] = "Correzione — Sfondi, bordi NineSlice e maniglie di ridimensionamento della chat nativa restano nascosti anche dopo aver selezionato Generale o Registro di combattimento. Chat V4 memorizza l'alfa originale di ogni elemento e lo ripristina esattamente alla disattivazione.",
    ["wn_401_chat_sidebar"]      = "Novità — La barra laterale ridisegnata aggiunge icone personalizzate e colori di stato dinamici per Amici, Gilda, Online/AFK/DND, voce, microfono e audio disattivati, oltre ai conteggi online e ai collegamenti per copia chat, browser bottino, impostazioni TomoMod e ultimo messaggio.",
    ["wn_401_chat_sidebar_assets"] = "Modifica — Le icone della barra laterale usano ora texture trasparenti 64×64 dedicate e sostituibili, incluse le varianti per stato, microfono e audio. I titoli e le descrizioni delle dieci infobolle, oltre al menu In linea/Assente/Non disturbare, sono tradotti in tutte le sei lingue supportate.",
    ["wn_401_chat_copy"]         = "Novità — Copia chat torna come finestra TomoMod completa: legge in tempo reale la scheda Blizzard attiva all'apertura, può essere spostata e ridimensionata, segue la dimensione del carattere della chat e offre i pulsanti tradotti Seleziona tutto e Chiudi, con una barra di scorrimento moderna e un'alternativa compatibile.",
    ["wn_401_chat_copy_clean"]   = "Modifica — La chat copiata diventa testo leggibile conservando colori dei messaggi, indicatori incursione, etichette dei collegamenti e nomi Battle.net disponibili. Grafica e codici di controllo vengono rimossi, i valori protetti ignorati, i testi brevi selezionati automaticamente e la vista si apre sulla riga più recente.",
    ["wn_401_chat_safe"]         = "Modifica — Chat V4 rispecchia la chat di Blizzard invece di sostituirne il percorso protetto. Blizzard mantiene il controllo del filtro del registro di combattimento, nessuna funzione FCF viene agganciata e disattivando Chat V4 viene ripristinata la presentazione nativa.",
    ["wn_401_chat_links"]        = "Correzione — I nomi dei giocatori, le etichette dei canali, i collegamenti agli oggetti e gli altri hyperlink Blizzard sono di nuovo cliccabili in Chat V4. L'area messaggi li inoltra al gestore nativo di Blizzard, mentre i link web TomoMod continuano ad aprire la finestra di copia.",
    ["wn_401_chat_mover"]        = "Correzione — Chat V4 dispone ora di un vero controllo di spostamento nella modalità Layout di TomoMod. Trascinare la sovrapposizione sull'intero pannello muove in tempo reale la chat Blizzard e la casella di immissione, salva la nuova posizione e libera temporaneamente il mouse nelle modalità Layout TomoMod e Modifica Blizzard prima di ripristinare link e scorrimento.",
    ["wn_401_chat_community"]    = "Novità — Una scheda Comunità localizzata riunisce i sussurri del personaggio ricevuti e inviati, i messaggi privati Battle.net e le chat di gilda e ufficiali da tutte le finestre chat Blizzard. I duplicati vengono rimossi tramite l'ID di riga; link cliccabili, stato non letto, immissione nativa e Copia chat restano disponibili.",
    ["wn_401_objective_chrome"]  = "Correzione — Lo sfondo completo e gli sfondi animati delle intestazioni del tracciamento obiettivi Blizzard non possono più riapparire dietro TomoMod dopo un aggiornamento. I valori alfa originali vengono ripristinati quando il tracciamento TomoMod viene disattivato.",
    ["wn_401_castbar_lifecycle"]  = "Correzione — La barra di lancio non sparisce più a metà di un incantesimo lungo. Un istantaneo o un proc scattato mentre stavi lanciando chiudeva la barra dell'incantesimo realmente in corso; ora la chiude soltanto la vera fine di quel lancio.",
    ["wn_401_castbar_identity"]   = "Correzione — Una barra di lancio reagisce ormai solo al proprio incantesimo. L'arresto, il fallimento o l'interruzione di un altro incantesimo non può più chiuderla né farla lampeggiare di rosso, perché ogni barra ricorda quale lancio l'ha aperta e confronta con quello ogni evento di chiusura.",
    ["wn_401_castbar_stale"]      = "Novità — Una barra di lancio che non riceve più notizie dal server si chiude un secondo dopo la fine prevista dell'incantesimo. Un messaggio perso durante un picco di latenza o una riconnessione a metà lancio poteva lasciare una barra bloccata sullo schermo; gli incantesimi potenziati sono esclusi, perché per progetto restano oltre la fine annunciata fino al rilascio.",
    ["wn_401_castbar_preview"]    = "Correzione — La modalità Layout e l'anteprima delle opzioni non si contendono più la barra di lancio del giocatore. Puoi spostarla dalla modalità Layout senza aprire la finestra delle opzioni, chiudere l'una non annulla più l'altra, ed entrare in combattimento chiude subito qualsiasi anteprima perché non copra mai un lancio reale.",
    ["wn_401_layout_chat_route"]  = "Correzione — L'ingranaggio della modalità Layout è di nuovo sulla finestra della chat. Puntava ancora ai riquadri della vecchia skin della chat, sostituita da Chat V4, quindi passare sopra il pannello della chat non offriva alcuna scorciatoia alle sue impostazioni.",
    ["wn_401_bags_v4"]            = "Novità — Bags V4 sostituisce la vecchia skin delle borse con una finestra interamente gestita da TomoMod: tutte le borse in un'unica griglia, il numero di spazi occupati e totali nell'intestazione, il tuo denaro nel piè di pagina e una cornice che puoi trascinare dove vuoi. Blizzard mantiene ogni azione sugli oggetti, quindi clic, trascinamento, vendita e descrizioni funzionano esattamente come prima.",
    ["wn_401_bags_search_sort"]   = "Novità — Cerca nelle borse mentre digiti, per nome oggetto o identificativo, e alterna la vista tra ordine borse, qualità, nome e livello oggetto dal pulsante nell'intestazione. L'ordinamento è puramente visivo: nulla viene mai spostato nelle borse reali, quindi non può interrompersi a metà né entrare in conflitto con il server.",
    ["wn_401_bags_sidebar"]       = "Novità — Una barra laterale tiene in vista gli oggetti fissati e quelli recenti. Un clic centrale fissa qualsiasi oggetto e il fissaggio resta legato al profilo; tutto ciò che arriva di nuovo nelle borse compare tra i Recenti. Un clic sinistro su una miniatura trova l'oggetto nella griglia.",
    ["wn_401_bags_slots"]         = "Novità — Gli spazi mostrano bordi colorati per qualità, il livello oggetto su armi e armature, un segno sugli oggetti fissati e un'icona attenuata su quelli bloccati. Quantità e animazioni di recupero continuano ad arrivare dal gioco stesso, e le borse dei componenti sono incluse quando il client le prevede. Bordi, livello oggetto e spazi vuoti si disattivano singolarmente.",
    ["wn_401_bags_native"]        = "Modifica — L'apertura e la chiusura seguono il gioco. Le scorciatoie delle borse, il micromenu, i mercanti, la cassetta postale e la banca aprono ancora la finestra, e le finestre delle borse di Blizzard vengono messe da parte finché Bags V4 è attivo e restituite intatte appena lo disattivi.",
    ["wn_401_bags_combat"]        = "Novità — Bags V4 non crea né sposta mai uno spazio mentre sei in combattimento. Tutto ciò che non può essere fatto in sicurezza viene messo in coda e applicato appena lo scontro finisce, mentre icone, quantità, blocchi e recuperi continuano ad aggiornarsi.",
    ["wn_401_bags_migration"]     = "Modifica — Le impostazioni delle borse esistenti vengono trasferite una sola volta: opacità, scala, dimensione degli spazi, spaziatura, numero di colonne, ordinamento, bordi di qualità, livello oggetto, spazi vuoti, barra di ricerca e posizione della finestra. La pagina iniziale ora inizializza e controlla direttamente Borse V4: disattivandolo, la finestra personalizzata si chiude e le borse Blizzard vengono ripristinate, mentre installazione e preset restano sincronizzati tramite il vecchio indicatore.",
    ["wn_401_bags_display_mode"]  = "Novità — Scegli come si aprono le borse. Combinate tiene tutto nell'unica finestra TomoMod; Separate le restituisce alle finestre individuali di Blizzard e si fa completamente da parte, rimettendo al suo posto l'impostazione di borse combinate del gioco.",
    ["wn_401_bags_options"]       = "Novità — Skins > Borse è ora una pagina di impostazioni viva. Modalità di visualizzazione, colonne, dimensione e spaziatura degli spazi, scala, opacità, ordinamento visivo, barra di ricerca, bordi di qualità, livello oggetto, spazi vuoti e quante miniature fissate e recenti tiene la barra laterale: tutto si applica all'istante, senza reload.",
    ["wn_401_bags_render"]        = "Correzione — Gli spazi usano ora un renderer minimo indipendente dalle regioni private di icona e quantità di Blizzard: icona visibile, quantità e recupero sono livelli TomoMod, mentre il pulsante oggetto nativo conserva tutte le azioni protette. Gli spazi validi di Midnight non possono più apparire vuoti.",
    ["wn_401_bags_native_restore"] = "Modifica — Le regioni private di icona e quantità di Blizzard restano trasparenti; TomoMod disegna icona visibile, quantità e recupero su livelli semplici e indipendenti. Il contenuto fisso borsa/spazio continua ad aggiornarsi in combattimento, mentre solo le modifiche al layout attendono la fine.",
    ["wn_401_bags_interactions"]  = "Correzione — Gli spazi mantengono intatti i percorsi protetti nativi di Blizzard per clic sinistro/destro e trascinamento. Le descrizioni vengono aggiunte tramite hook senza sostituire gli script del modello, il clic centrale viene osservato separatamente per fissare gli oggetti e i livelli visivi TomoMod restano non interattivi.",
    ["wn_401_bags_button_visibility"] = "Correzione — Ogni pulsante oggetto protetto viene mostrato esplicitamente quando è creato, disegnato e posizionato nella griglia, impedendo che uno stato nascosto del pool lasci uno spazio visibile vuoto o incapace di ricevere clic.",
    ["wn_401_bags_empty_quality"] = "Modifica — Gli spazi vuoti usano un riempimento scuro minimo e un bordo tenue; i bordi qualità restano forti sopra la qualità comune e discreti sotto. Il livello oggetto rimane in alto a sinistra sul proprio fondo di contrasto, separato dalla quantità in basso a destra.",
    ["wn_401_bags_text_polish"]   = "Modifica — Quantità e livelli oggetto si adattano alla dimensione scelta per gli spazi e poggiano su discreti fondi scuri. Le quantità restano in basso a destra e i livelli in alto a sinistra, così le due etichette non si sovrappongono.",
    ["wn_401_bags_surface_polish"] = "Modifica — Superfici, intestazione, ricerca, barra laterale e piè di pagina di Bags V4 sono leggermente più chiari. I messaggi vuoti di Fissati e Recenti usano un colore più leggibile, larghezza dinamica e fino a due righe per contenere tutte le traduzioni.",
    ["wn_401_bags_fit"]           = "Novità — La finestra combinata si adatta ora al numero reale di oggetti visualizzati. Mantiene il numero di colonne richiesto quando possibile, aggiunge colonne prima di introdurre una barra di scorrimento se manca altezza e consente lo scorrimento solo quando nessuna geometria a schermo può contenere l'intera griglia; le barre inutili restano nascoste.",
    ["wn_401_bags_slot_identity"] = "Modificato — Gli scomparti mostrano ora a colpo d'occhio la loro funzione: bordo verde menta/turchese per le borse normali e azzurro chiaro per la borsa dei reagenti. Gli scomparti occupati mantengono il colore della qualità dell'oggetto quando i bordi qualità sono attivi; altrimenti conservano il bordo del loro tipo di borsa.",
    ["wn_401_mplus_score_columns"] = "Corretto — Le colonne Punteggio attuale, Punteggio obiettivo, Guadagno stimato e Potenziale del Pianificatore punteggio ora condividono la larghezza disponibile della scheda invece di usare posizioni fisse. Potenziale non supera più il bordo destro con le dimensioni predefinite dello Studio o aumentando la scala del testo.",
    ["wn_401_actionbar_negative_spacing"] = "Corretto — I pulsanti delle barre delle azioni con spaziatura negativa non sovrappongono più le proprie aree cliccabili. TomoMod divide a metà i pixel condivisi, quindi fare clic o trascinare un incantesimo seleziona sempre il pulsante sotto il puntatore; la spaziatura zero o positiva mantiene l'intera area cliccabile.",
    ["wn_401_raid_position"]      = "Corretto — Le posizioni dei riquadri incursione usano ora il motore di layout condiviso durante il salvataggio e il ripristino. I formati esistenti restano compatibili e i riquadri spostati non saltano più dopo un ricaricamento o una modifica della risoluzione o della scala dell'interfaccia.",
    ["wn_401_class_reminder_position"] = "Corretto — Il promemoria di classe ora migra l'ancoraggio salvato, lo adatta alla risoluzione corrente e converte gli offset secondo la propria scala. Non si sposta più dopo un ricaricamento o una modifica dello schermo.",
    ["wn_401_objective_position"] = "Corretto — Le posizioni del tracciamento obiettivi ora riconoscono sia gli ancoraggi precedenti sia quelli di Layout V4, si adattano dalla risoluzione salvata e tengono conto della scala propria del riquadro. Non cambiano più ancoraggio né scorrono sullo schermo dopo un ricaricamento o una modifica dello schermo.",
    ["wn_401_layout_scaled_positions"] = "Corretto — Layout V4 ora salva gli offset in unità UIParent e li riconverte tramite la scala effettiva di ogni riquadro durante il ripristino. I riquadri ridimensionati non moltiplicano più le coordinate e non si spostano dopo ricaricamenti ripetuti.",
    ["wn_401_layout_minimap"]     = "Corretto — Le particolari coordinate precedenti della minimappa vengono normalizzate una sola volta in Layout V4 senza spostarla. Il confronto della posizione fisica ignora gli innocui cambi interni di ancoraggio di Blizzard, evitando salti e disallineamenti momentanei con la cornice.",
    ["wn_401_layout_secondary_frames"] = "Modificato — La barra d'incantazione del giocatore, le barre delle risorse e il contatore delle resurrezioni in combattimento ora salvano e ripristinano la posizione tramite il motore condiviso. Restano stabili dopo ricaricamenti o modifiche di scala e risoluzione, mantenendo i fallback di compatibilità.",
    ["wn_401_layout_mythic_tracker"] = "Corretto — Il tracciatore Mitiche+ applica ora la scala prima della posizione V4 e usa lo stesso motore per spostamenti, ripristini e anteprime della modalità Layout. Annullare il posizionamento nello Studio ripristina la posizione completa invece di riportarla al formato precedente.",
    ["wn_401_layout_v4_anchors"]  = "Novità — Chat V4 e Bags V4 dichiarano ora i loro veri ancoraggi spostabili in Layout V4. Migrazione delle posizioni, preimpostazioni di risoluzione, registrazione dei riferimenti e importazioni selettive possono includere i riquadri attuali invece dei vecchi ancoraggi della chat.",
    ["wn_401_bags_position"]      = "Corretto — Bags V4 ora salva la posizione fisica della finestra dopo il trascinamento e la ripristina tramite Layout V4. Spostare o ridimensionare le borse non riutilizza più gli offset precedenti al trascinamento e non fa più slittare la finestra dopo i ricaricamenti successivi.",
    ["wn_401_layout_v4_routes"]   = "Corretto — Gli ingranaggi della modalità Layout sulle barre delle azioni TUI e Bags V4 aprono ora la pagina corretta Barre delle azioni o Skins. Un controllo automatico verifica inoltre che ogni ancoraggio spostabile dichiarato abbia una rotta attiva verso le opzioni.",
    ["wn_401_layout_pixel_perfect"] = "Novità — Layout V4.1 può allineare ogni posizione salvata dal motore di layout condiviso al pixel fisico più vicino. Ricava la dimensione reale del pixel dalla risoluzione fisica, resta facoltativo e non cambia il comportamento V4 esistente quando è disattivato.",
    ["wn_401_layout_nudger"]      = "Novità — La modalità Layout ottiene un pannello Pixel Perfect / Nudger per l'elemento spostabile selezionato al passaggio del mouse. Spostalo di 1, 5 o 10 pixel fisici, leggi le coordinate del centro, centra un asse o ripristina la posizione predefinita; i riquadri protetti non vengono toccati in combattimento.",
    ["wn_401_layout_mirror"]      = "Novità — La simmetria tra Giocatore e Bersaglio mantiene i due riquadri unità speculari in orizzontale rispetto al centro fisico dello schermo e alla stessa altezza. Attivandola, il Bersaglio viene subito allineato dal Giocatore; i salvataggi successivi di uno aggiornano l'altro senza ricorsione.",
    ["wn_401_layout_unitframes"]  = "Modifica — Le posizioni dei riquadri Giocatore, Bersaglio e Focus ora vengono salvate e ripristinate tramite il motore Layout V4 condiviso anziché con un percorso separato a coordinate assolute. Ottengono così adattamento alla risoluzione, allineamento Pixel Perfect e notifiche degli ancoraggi collegati, mantenendo fallback compatibili.",
    ["wn_401_layout_font_symbols"] = "Corretto — Il pannello Pixel Perfect / Nudger usa ora indicatori di direzione, etichette Giocatore/Bersaglio e segnaposto per coordinate non disponibili in testo semplice compatibile con i font. I font di WoW privi dei precedenti simboli Unicode non mostrano più rombi di glifi mancanti.",
    ["wn_401_tomolayout_selection"] = "Modifica — Il pannello di posizionamento preciso si chiama ora TomoLayout e resta nascosto finché non fai clic o inizi a trascinare un elemento spostabile supportato. Gli hook di selezione usano le sovrapposizioni di spostamento dedicate quando disponibili, senza modificare i pulsanti unità protetti.",
    ["wn_401_tomolayout_config"] = "Modifica — TomoLayout include ora il pulsante contestuale Configura per l'elemento selezionato. Il precedente scanner continuo dell'elemento sotto il mouse e il suo ingranaggio mobile restano disattivati, eliminando un ciclo di controllo permanente dalla modalità Layout.",
    ["wn_401_tomolayout_highlight"] = "Novità — L'elemento spostabile selezionato viene evidenziato con un contorno turchese e un leggero riempimento. Bordo e distanza restano di due pixel fisici con qualsiasi scala dell'interfaccia, seguono il riquadro durante lo spostamento e scompaiono con la selezione, il riquadro o la modalità Layout.",
    ["wn_401_azure_identity"]     = "Modifica — L'identità visiva di TomoMod è nuovamente unificata attorno all'azzurro #2E9DD8 nel nucleo, nei moduli, nelle opzioni e negli addon caricati su richiesta. La tavolozza condivisa definisce gli accenti normale, al passaggio e premuto, oltre a superfici scure leggermente blu; i colori funzionali di successo, avviso, errore, classe e qualità restano indipendenti.",
    ["wn_401_azure_movers"]       = "Modifica — Le sovrapposizioni della modalità Layout usano ora un gradiente opaco dall'azzurro al quasi bianco, un bordo ad alto contrasto e testo blu scuro centrato con un'ombra chiara. La fascia interna del nome è stata rimossa, così gli elementi compatti non sembrano più una scatola dentro l'altra e le chiamate ripetute non sovrappongono texture.",
    ["wn_401_azure_mover_labels"] = "Corretto — Riquadri boss, promemoria di classe, barra dei consumabili e tracciatore obiettivi riutilizzano ora l'etichetta comune invece di sovrapporre testo. Le modifiche di scala del tracciatore aggiornano questa etichetta localizzata e l'elemento mobile delle borse usa il nome già tradotto.",
    ["wn_401_azure_mover_coverage"] = "Modifica — Il renderer condiviso degli elementi mobili ora include anche bussola, supporti del gestore recuperi, ancoraggi dei riquadri, minimappa, barra di lancio del giocatore e barra dei totem. Il comportamento di trascinamento e salvataggio resta invariato, mentre sono stati rimossi sfondi, bordi ed etichette duplicate locali ormai obsoleti.",
    ["wn_401_azure_guard"]        = "Interno — Il test dell'identità analizza più di 100 sorgenti Lua, verifica la coerenza esadecimale/RGB, rifiuta il precedente verde menta e accenti turchesi residui inattesi, controlla dieci elementi mobili migrati e fallisce se uno di essi ricrea un'etichetta duplicata.",
})

TomoMod_RegisterLocale("ptBR", {
    ["section_blizzard_auras"]   = "Quadros de auras da Blizzard",
    ["info_blizzard_auras"]      = "Controla os quadros padrão de benefícios e penalidades da Blizzard sem afetar as auras dos quadros de unidade do TomoMod. As alterações são imediatas e não exigem recarregamento.",
    ["opt_blizzard_auras_manage"] = "Permitir que o TomoMod gerencie os quadros de auras da Blizzard",
    ["opt_blizzard_buffs"]       = "Mostrar benefícios da Blizzard",
    ["opt_blizzard_debuffs"]     = "Mostrar penalidades da Blizzard",
    ["layout_configure"]         = "Configurar este elemento",
    ["wn_401_layout_cogs"]       = "Novo — O modo Layout agora mostra uma engrenagem ao passar o mouse sobre um elemento móvel. Um clique abre diretamente a página de opções correspondente do TomoMod.",
    ["wn_401_blizzard_auras"]    = "Novo — Interface > Geral agora permite ocultar separadamente os quadros de benefícios e penalidades da Blizzard, ao vivo e sem recarregar.",
    ["wn_401_chat_v4"]           = "Novo — O Chat V4 reconstrói a apresentação do bate-papo com uma interface escura do TomoMod para mensagens, abas encaixadas, caixa de entrada nativa e uma nova barra lateral, enquanto a Blizzard continua responsável pela entrega, formatação e interações seguras.",
    ["wn_401_chat_options"]      = "Novo — Skins > Janela de bate-papo agora é o centro de controle ao vivo do Chat V4. Ative, ajuste a opacidade do fundo e o tamanho da fonte, escolha o comportamento das mensagens, personalize a barra lateral e defina o limite de linhas da cópia; cada alteração é aplicada imediatamente e sem recarregar.",
    ["wn_401_chat_message_opacity"] = "Novo — A opacidade do quadro e a da área de mensagens agora são independentes. O segundo controle altera apenas o fundo atrás do texto do bate-papo, até ficar totalmente transparente, sem esmaecer abas, barra lateral ou caixa de entrada; os perfis existentes mantêm a aparência anterior.",
    ["wn_401_chat_messages"]     = "Novo — A apresentação pode adicionar ou preservar horários, abreviar nomes localizados de canais, desaparecer após dois minutos, transformar emoticons comuns em símbolos e colorir por classe as menções a jogadores conhecidos. Alterar uma opção reconstrói as linhas existentes para manter todo o histórico visível consistente.",
    ["wn_401_chat_urls"]         = "Novo — Endereços HTTP(S) e www comuns viram links turquesa clicáveis sem alterar os hiperlinks existentes da Blizzard. Clicar abre uma janela focada para Ctrl+C e a pontuação no fim da frase fica fora do link.",
    ["wn_401_chat_sidebar_options"] = "Novo — Coloque a barra lateral à esquerda ou direita, ajuste largura, tamanho e espaçamento dos botões, mostre ou oculte cada atalho e escolha entre 50 e 1.000 linhas para a cópia do bate-papo. As configurações antigas de mensagens do Chat Skin migram uma única vez para o Chat V4.",
    ["wn_401_chat_wiring"]       = "Mudança — O Chat V4 agora é o único módulo público de bate-papo nos padrões, no registro de módulos, no painel inicial, no instalador, nas predefinições, nas importações de perfil e no ajuste por resolução. Os bancos de dados antigos do bate-papo permanecem apenas como fontes internas de migração.",
    ["wn_401_chat_combatlog"]    = "Mudança — O registro de combate agora usa a superfície do Chat V4 quando selecionado, enquanto a Blizzard continua filtrando e formatando primeiro cada linha. O TomoMod apenas espelha a saída final e nunca substitui as APIs do registro de combate.",
    ["wn_401_chat_journal_controls"] = "Novo — A barra de filtros rápidos do registro de combate da Blizzard agora fica ancorada no topo da área de mensagens do Chat V4, que reserva espaço para ela. Ela se oculta nas outras abas e volta exatamente à posição e visibilidade originais quando o Chat V4 é desativado, sem vinculá-la a outro quadro nem substituir os filtros.",
    ["wn_401_chat_phase21_polish"] = "Mudança — As abas espelhadas agora ficam dentro da borda superior do painel. O atalho Emotes foi removido da barra lateral, das opções e dos layouts salvos; Copiar bate-papo, Saques, Configurações e Última mensagem ficam organizados em pares.",
    ["wn_401_chat_tabs"]         = "Novo — As abas do Chat V4 agora são controles interativos organizados da esquerda para a direita em sua própria barra, incluindo um registro de combate desencaixado. Cliques esquerdo e direito são encaminhados à aba invisível da Blizzard, preservando a seleção e os menus de contexto nativos enquanto o sublinhado ativo e as mensagens não lidas ficam sincronizados.",
    ["wn_401_chat_native_chrome"] = "Corrigido — Fundos, bordas NineSlice e alças de redimensionamento do chat nativo permanecem ocultos mesmo após selecionar Geral ou Registro de combate. O Chat V4 salva o alfa original de cada elemento e o restaura exatamente ao ser desativado.",
    ["wn_401_chat_sidebar"]      = "Novo — A barra lateral redesenhada adiciona ícones personalizados e cores de estado dinâmicas para Amigos, Guilda, Online/AFK/DND, voz, microfone e áudio desativados, além de contagens online e atalhos para cópia do bate-papo, navegador de saques, configurações do TomoMod e última mensagem.",
    ["wn_401_chat_sidebar_assets"] = "Mudança — Os ícones da barra lateral agora usam texturas transparentes 64×64 dedicadas e substituíveis, incluindo variantes de status, microfone e áudio. Os títulos e descrições das dez dicas, além do menu Online/Ausente/Não perturbe, estão traduzidos nos seis idiomas compatíveis.",
    ["wn_401_chat_copy"]         = "Novo — Copiar bate-papo volta como uma janela completa do TomoMod: lê ao vivo a aba ativa da Blizzard ao abrir, pode ser movida e redimensionada, acompanha o tamanho da fonte do bate-papo e oferece botões traduzidos para Selecionar tudo e Fechar, com uma barra de rolagem moderna e uma alternativa compatível.",
    ["wn_401_chat_copy_clean"]   = "Mudança — O bate-papo copiado vira texto legível e preserva as cores das mensagens, marcadores de raide, rótulos de links e nomes Battle.net disponíveis. Elementos gráficos e códigos de controle são removidos, valores protegidos são ignorados, textos curtos são selecionados automaticamente e a visualização abre na linha mais recente.",
    ["wn_401_chat_safe"]         = "Mudança — O Chat V4 espelha o bate-papo da Blizzard em vez de substituir seu caminho seguro. A Blizzard mantém o controle da filtragem do registro de combate, nenhuma função FCF é vinculada e desativar o Chat V4 restaura a apresentação nativa.",
    ["wn_401_chat_links"]        = "Corrigido — Nomes de jogadores, rótulos de canais, links de itens e outros hiperlinks da Blizzard voltam a ser clicáveis no Chat V4. A área de mensagens os encaminha ao gerenciador nativo da Blizzard, enquanto os links web do TomoMod continuam abrindo a janela de cópia.",
    ["wn_401_chat_mover"]        = "Corrigido — O Chat V4 agora possui um controle de movimento real no modo Layout do TomoMod. Arrastar a sobreposição que cobre todo o painel move ao vivo o chat da Blizzard e sua caixa de entrada, salva a nova posição e libera temporariamente o mouse nos modos Layout do TomoMod e Edição da Blizzard antes de restaurar links e rolagem.",
    ["wn_401_chat_community"]    = "Novo — Uma aba Comunidade localizada reúne sussurros de personagem recebidos e enviados, mensagens privadas Battle.net e os bate-papos de guilda e oficiais de todas as janelas de chat da Blizzard. Duplicatas são removidas pelo ID da linha; links clicáveis, estado não lido, entrada nativa e Copiar bate-papo continuam disponíveis.",
    ["wn_401_objective_chrome"]  = "Corrigido — O fundo completo e os fundos animados dos cabeçalhos do rastreador de objetivos da Blizzard não podem mais reaparecer atrás do TomoMod após uma atualização. Os valores alfa originais são restaurados quando o rastreador do TomoMod é desativado.",
    ["wn_401_castbar_lifecycle"]  = "Correção — Sua barra de conjuração não some mais no meio de uma magia longa. Uma magia instantânea ou um proc disparado enquanto você conjurava fechava a barra da magia que estava realmente em andamento; agora só o fim verdadeiro dessa conjuração a fecha.",
    ["wn_401_castbar_identity"]   = "Correção — Uma barra de conjuração só reage à própria conjuração. A parada, a falha ou a interrupção de outra magia não pode mais fechá-la nem fazê-la piscar em vermelho, porque cada barra lembra qual conjuração a abriu e confere cada evento de encerramento com essa identidade.",
    ["wn_401_castbar_stale"]      = "Novo — Uma barra de conjuração que para de receber notícias do servidor se fecha um segundo depois do fim previsto da magia. Uma mensagem perdida num pico de latência ou uma reconexão no meio da conjuração podia deixar uma barra congelada na tela; magias de intensificação ficam de fora, já que devem se manter além do fim anunciado até você soltar.",
    ["wn_401_castbar_preview"]    = "Correção — O modo Layout e a prévia das opções não disputam mais a barra de conjuração do jogador. Você pode movê-la pelo modo Layout sem abrir a janela de opções, fechar uma não cancela mais a outra, e entrar em combate fecha qualquer prévia na hora para que ela nunca fique por cima de uma conjuração real.",
    ["wn_401_layout_chat_route"]  = "Correção — A engrenagem do modo Layout voltou à janela de bate-papo. Ela ainda apontava para os quadros da antiga skin do bate-papo, substituída pelo Chat V4, então passar o mouse sobre o painel não oferecia nenhum atalho para as configurações.",
    ["wn_401_bags_v4"]            = "Novo — O Bags V4 substitui a antiga skin das bolsas por uma janela totalmente gerenciada pelo TomoMod: todas as bolsas em uma única grade, o número de espaços ocupados e totais no cabeçalho, seu dinheiro no rodapé e um quadro que você arrasta para onde quiser. A Blizzard continua responsável por todas as ações com itens, então clicar, arrastar, vender e as dicas funcionam exatamente como antes.",
    ["wn_401_bags_search_sort"]   = "Novo — Busque nas bolsas enquanto digita, por nome do item ou identificador, e alterne a exibição entre ordem das bolsas, qualidade, nome e nível do item pelo botão do cabeçalho. A ordenação é apenas visual: nada é movido dentro das suas bolsas reais, então ela não pode ser interrompida pela metade nem entrar em conflito com o servidor.",
    ["wn_401_bags_sidebar"]       = "Novo — Uma barra lateral mantém à vista seus itens fixados e recentes. O clique do meio fixa qualquer item e a fixação fica salva no seu perfil; tudo que chega de novo nas bolsas aparece em Recentes. O clique esquerdo em uma miniatura localiza o item na grade.",
    ["wn_401_bags_slots"]         = "Novo — Os espaços mostram bordas coloridas por qualidade, o nível do item em armas e armaduras, uma marca nos itens fixados e um ícone esmaecido nos bloqueados. As quantidades e as animações de recarga continuam vindo do próprio jogo, e as bolsas de reagentes são incluídas quando o cliente as oferece. Bordas, nível do item e espaços vazios podem ser desativados separadamente.",
    ["wn_401_bags_native"]        = "Mudança — Abrir e fechar acompanha o jogo. Seus atalhos de bolsa, o micromenu, os vendedores, a caixa de correio e o banco continuam abrindo a janela, e os quadros de bolsa da Blizzard ficam guardados enquanto o Bags V4 está ativo e são devolvidos intactos assim que você o desativa.",
    ["wn_401_bags_combat"]        = "Novo — O Bags V4 nunca cria nem move um espaço enquanto você está em combate. Tudo que não pode ser feito com segurança entra na fila e é aplicado assim que a luta termina, enquanto ícones, quantidades, bloqueios e recargas continuam se atualizando.",
    ["wn_401_bags_migration"]     = "Mudança — Suas configurações de bolsa existentes são transferidas uma vez: opacidade, escala, tamanho do espaço, espaçamento, número de colunas, ordenação, bordas de qualidade, nível do item, espaços vazios, barra de busca e posição da janela. O painel inicial agora inicializa e controla diretamente o Bolsas V4: desativá-lo fecha a janela personalizada e restaura as bolsas da Blizzard, enquanto o instalador e as predefinições permanecem sincronizados pelo indicador antigo.",
    ["wn_401_bags_display_mode"]  = "Novo — Escolha como suas bolsas abrem. Combinadas mantém tudo na única janela do TomoMod; Separadas as devolve às janelas individuais da Blizzard e sai completamente do caminho, recolocando no lugar a própria configuração de bolsas combinadas do jogo.",
    ["wn_401_bags_options"]       = "Novo — Skins > Bolsas agora é uma página de configurações ao vivo. Modo de exibição, colunas, tamanho e espaçamento dos espaços, escala, opacidade, ordenação visual, barra de busca, bordas de qualidade, nível do item, espaços vazios e quantas miniaturas fixadas e recentes a barra lateral guarda: tudo se aplica na hora, sem recarregar.",
    ["wn_401_bags_render"]        = "Correção — Os espaços agora usam um renderizador mínimo independente das regiões privadas de ícone e quantidade da Blizzard: ícone visível, quantidade e recarga são camadas do TomoMod, enquanto o botão de item nativo mantém todas as ações seguras. Espaços válidos de Midnight não podem mais parecer vazios.",
    ["wn_401_bags_native_restore"] = "Mudança — As regiões privadas de ícone e quantidade da Blizzard permanecem transparentes; o TomoMod desenha ícone visível, quantidade e recarga em camadas simples e independentes. O conteúdo fixo de bolsa/espaço continua atualizando em combate, enquanto apenas mudanças de layout aguardam o fim.",
    ["wn_401_bags_interactions"]  = "Correção — Os espaços mantêm intactos os caminhos seguros nativos da Blizzard para clique esquerdo/direito e arraste. As dicas são adicionadas por hooks sem substituir os scripts do modelo, o clique do meio é observado separadamente para fixar itens e as camadas visuais do TomoMod continuam não interativas.",
    ["wn_401_bags_button_visibility"] = "Correção — Cada botão de item seguro é mostrado explicitamente ao ser criado, renderizado e posicionado na grade, impedindo que um estado oculto do pool deixe um espaço visível vazio ou incapaz de receber cliques.",
    ["wn_401_bags_empty_quality"] = "Mudança — Espaços vazios usam um preenchimento escuro mínimo e uma borda suave; as bordas de qualidade continuam fortes acima da qualidade comum e discretas abaixo. O nível do item fica no alto à esquerda sobre seu próprio fundo de contraste, separado da quantidade embaixo à direita.",
    ["wn_401_bags_text_polish"]   = "Mudança — Quantidades e níveis de item se adaptam ao tamanho escolhido para os espaços e ficam sobre fundos escuros discretos. As quantidades permanecem embaixo à direita e os níveis no alto à esquerda, evitando sobreposição entre os dois textos.",
    ["wn_401_bags_surface_polish"] = "Mudança — Superfícies, cabeçalho, busca, barra lateral e rodapé do Bags V4 estão ligeiramente mais claros. As mensagens vazias de Fixados e Recentes usam cor mais legível, largura dinâmica e até duas linhas para acomodar todas as traduções.",
    ["wn_401_bags_fit"]           = "Novo — A janela combinada agora se ajusta ao número real de itens exibidos. Ela mantém o número de colunas solicitado quando possível, adiciona colunas antes de introduzir uma barra de rolagem se faltar altura e só permite rolagem quando nenhuma geometria na tela consegue conter toda a grade; barras desnecessárias permanecem ocultas.",
    ["wn_401_bags_slot_identity"] = "Alterado — Os espaços agora identificam sua função de imediato: contorno verde-menta/turquesa para bolsas normais e azul-celeste para a bolsa de reagentes. Espaços ocupados continuam usando a cor da qualidade do item quando as bordas de qualidade estão ativadas; caso contrário, mantêm o contorno do tipo de bolsa.",
    ["wn_401_mplus_score_columns"] = "Corrigido — As colunas Pontuação atual, Pontuação-alvo, Ganho estimado e Potencial do Planejador de pontuação agora dividem a largura disponível do painel, em vez de usar posições fixas. Potencial não ultrapassa mais a borda direita no tamanho padrão do Studio nem quando a escala do texto é aumentada.",
    ["wn_401_actionbar_negative_spacing"] = "Corrigido — Os botões das barras de ação com espaçamento negativo não sobrepõem mais suas áreas clicáveis. O TomoMod divide os pixels compartilhados ao meio, então clicar ou arrastar uma magia sempre atinge o botão sob o ponteiro; espaçamento zero ou positivo mantém toda a área de clique.",
    ["wn_401_raid_position"]      = "Corrigido — As posições dos quadros de raide agora usam o mecanismo de layout compartilhado ao serem salvas e restauradas. Os formatos existentes continuam compatíveis e os quadros movidos não saltam mais após recarregar ou alterar a resolução ou a escala da interface.",
    ["wn_401_class_reminder_position"] = "Corrigido — O lembrete de classe agora migra sua âncora salva, ajusta-a à resolução atual e converte os deslocamentos conforme sua própria escala. Ele não deriva mais após recarregar ou alterar a tela.",
    ["wn_401_objective_position"] = "Corrigido — As posições do rastreador de objetivos agora reconhecem tanto as âncoras antigas quanto as do Layout V4, ajustam-se a partir da resolução salva e consideram a escala do próprio quadro. O rastreador não muda mais de âncora nem se desloca pela tela após recarregar ou alterar a configuração de vídeo.",
    ["wn_401_layout_scaled_positions"] = "Corrigido — O Layout V4 agora salva deslocamentos em unidades do UIParent e os reconverte pela escala efetiva de cada quadro ao restaurar. Quadros redimensionados não multiplicam mais suas coordenadas nem se deslocam após recarregamentos repetidos.",
    ["wn_401_layout_minimap"]     = "Corrigido — As coordenadas antigas e especiais do minimapa são normalizadas uma única vez no Layout V4 sem movê-lo. A comparação da posição física ignora mudanças internas e inofensivas de âncora feitas pela Blizzard, evitando saltos e desalinhamentos momentâneos com sua moldura.",
    ["wn_401_layout_secondary_frames"] = "Alterado — A barra de lançamento do jogador, as barras de recursos e o contador de ressurreições em combate agora salvam e restauram suas posições pelo mecanismo compartilhado. Elas permanecem estáveis após recarregar ou alterar escala e resolução, mantendo alternativas de compatibilidade.",
    ["wn_401_layout_mythic_tracker"] = "Corrigido — O rastreador de Mítica+ agora aplica a escala antes da posição V4 e usa o mesmo mecanismo para mover, redefinir e exibir prévias do modo Layout. Cancelar o posicionamento no Studio restaura a posição completa, em vez de convertê-la novamente para o formato antigo.",
    ["wn_401_layout_v4_anchors"]  = "Novo — Chat V4 e Bags V4 agora declaram suas âncoras móveis reais ao Layout V4. Migração de posições, predefinições de resolução, registro de referências e importações seletivas podem incluir os quadros atuais em vez das âncoras antigas do chat.",
    ["wn_401_bags_position"]      = "Corrigido — Bags V4 agora salva a posição física da janela após arrastá-la e a restaura pelo Layout V4. Mover ou redimensionar as bolsas não reutiliza mais os deslocamentos anteriores ao arrasto nem faz a janela derivar após recarregamentos posteriores.",
    ["wn_401_layout_v4_routes"]   = "Corrigido — As engrenagens do modo Layout nas barras de ação TUI e no Bags V4 agora abrem a página correta de Barras de ação ou Skins. Uma verificação automática também garante que cada âncora móvel declarada tenha uma rota ativa para as opções.",
    ["wn_401_layout_pixel_perfect"] = "Novo — O Layout V4.1 pode alinhar cada posição salva pelo mecanismo de layout compartilhado ao pixel físico mais próximo. Ele calcula o tamanho real do pixel pela resolução física, permanece opcional e mantém o comportamento V4 existente quando desativado.",
    ["wn_401_layout_nudger"]      = "Novo — O modo Layout ganha um painel Pixel Perfect / Nudger para o elemento móvel selecionado ao passar o mouse. Mova-o em 1, 5 ou 10 pixels físicos, consulte as coordenadas do centro, centralize um dos eixos ou restaure a posição padrão; quadros protegidos não são alterados em combate.",
    ["wn_401_layout_mirror"]      = "Novo — O espelhamento entre Jogador e Alvo mantém os dois quadros de unidade simétricos horizontalmente em relação ao centro físico da tela e na mesma altura. Ao ativar, o Alvo é alinhado imediatamente a partir do Jogador; salvamentos posteriores de qualquer quadro atualizam o outro sem recursão.",
    ["wn_401_layout_unitframes"]  = "Mudança — As posições dos quadros de Jogador, Alvo e Foco agora são salvas e restauradas pelo mecanismo compartilhado Layout V4 em vez de um caminho separado de coordenadas absolutas. Assim, recebem ajuste por resolução, alinhamento Pixel Perfect e notificações de âncoras vinculadas, com alternativas compatíveis.",
    ["wn_401_layout_font_symbols"] = "Corrigido — O painel Pixel Perfect / Nudger agora usa indicadores de direção, rótulos Jogador/Alvo e marcadores de coordenadas indisponíveis em texto simples compatível com as fontes. As fontes do WoW sem os símbolos Unicode anteriores não exibem mais losangos de glifos ausentes.",
    ["wn_401_tomolayout_selection"] = "Mudança — O painel de posicionamento preciso agora se chama TomoLayout e permanece oculto até você clicar ou começar a arrastar um elemento móvel compatível. Os vínculos de seleção usam sobreposições de movimento dedicadas quando disponíveis, sem modificar botões de unidade protegidos.",
    ["wn_401_tomolayout_config"] = "Mudança — O TomoLayout agora inclui o botão contextual Configurar do elemento selecionado. O antigo scanner contínuo do foco do mouse e sua engrenagem flutuante permanecem desativados, eliminando um ciclo permanente de consulta do modo Layout.",
    ["wn_401_tomolayout_highlight"] = "Novo — O elemento móvel selecionado recebe um contorno turquesa com um preenchimento discreto. A borda e o espaçamento mantêm dois pixels físicos em qualquer escala da interface, acompanham o quadro durante o movimento e desaparecem com a seleção, o quadro ou o modo Layout.",
    ["wn_401_azure_identity"]     = "Mudança — A identidade visual do TomoMod volta a ser unificada em torno do azul-celeste #2E9DD8 no núcleo, nos módulos, nas opções e nos complementos carregados sob demanda. A paleta compartilhada define os realces normal, sob o cursor e pressionado, além de superfícies escuras levemente azuladas; cores funcionais de sucesso, aviso, erro, classe e qualidade permanecem independentes.",
    ["wn_401_azure_movers"]       = "Mudança — As sobreposições do modo Layout agora usam um gradiente opaco do azul-celeste ao quase branco, uma borda de alto contraste e texto azul-escuro centralizado com sombra clara. A faixa interna do nome foi removida, para que elementos compactos não pareçam uma caixa dentro de outra, e chamadas repetidas não empilhem texturas.",
    ["wn_401_azure_mover_labels"] = "Corrigido — Quadros de chefes, lembrete de classe, barra de consumíveis e rastreador de objetivos agora reutilizam o rótulo compartilhado em vez de sobrepor textos. Mudanças de escala do rastreador atualizam esse rótulo localizado, e o elemento móvel das bolsas usa seu nome já traduzido.",
    ["wn_401_azure_mover_coverage"] = "Mudança — O renderizador compartilhado dos elementos móveis agora também abrange a bússola, os suportes do gerenciador de recargas, as âncoras de quadros, o minimapa, a barra de lançamento do jogador e a barra de totens. O comportamento existente de arrastar e salvar permanece igual, enquanto fundos, bordas e rótulos locais duplicados e obsoletos foram removidos.",
    ["wn_401_azure_guard"]        = "Interno — O teste de identidade percorre mais de 100 fontes Lua, verifica a consistência hexadecimal/RGB, rejeita o antigo verde-menta e realces turquesa residuais inesperados, confere dez elementos móveis migrados e falha se algum deles recriar um rótulo duplicado.",
})
